class NativeGraphDialogueReject(RuntimeError):
    """Rejected current graph/dialogue sample; retry with another seed/API attempt."""


class NativeGraphDialogueAnchorLeakReject(NativeGraphDialogueReject):
    """Rejected because a temporary alignment anchor leaked into solver-visible text."""


def normalize_space(value: Any) -> str:
    return re.sub(r"\s+", " ", str(value or "")).strip()


def normalize_text(value: Any) -> str:
    return re.sub(r"[^a-z0-9]+", " ", normalize_space(value).lower()).strip()


def token_set(value: Any) -> set[str]:
    return {token for token in normalize_text(value).split() if len(token) >= 3}


def _event_lexical_token_set(value: Any) -> set[str]:
    """Keep exact numeric facts while retaining the existing lexical noise floor."""

    raw = "" if value is None else str(value)
    normalized = re.sub(
        r"[^a-z0-9]+",
        " ",
        re.sub(r"\s+", " ", raw).strip().lower(),
    ).strip()
    return {
        token
        for token in normalized.split()
        if len(token) >= 3 or token.isdigit()
    }


def _exact_integer_surface_supported(value: int, turn_text: Any) -> bool:
    """Require a signed, whole-token decimal surface for one JSON integer fact."""

    surface = str(value)
    pattern = re.compile(
        rf"(?<![A-Za-z0-9_.+\-]){re.escape(surface)}"
        rf"(?![A-Za-z0-9_])(?![.,]\d)"
    )
    return pattern.search(normalize_space(turn_text)) is not None


def stable_hash(value: Any, *, length: int = 16) -> str:
    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, default=str)
    return hashlib.sha1(payload.encode("utf-8")).hexdigest()[:length]


def canonical_json_sha256(value: Any) -> str:
    """Return a stable full-content digest for persisted graph lineage."""

    return hashlib.sha256(
        json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ).encode("utf-8")
    ).hexdigest()


def turn_sort_key(turn_id: Any) -> tuple[int, int, str]:
    match = re.match(r"^D(\d+):(\d+)$", str(turn_id or ""))
    if match:
        return int(match.group(1)), int(match.group(2)), str(turn_id)
    return 999999, 999999, str(turn_id or "")


def normalize_turn_ids(value: Any) -> list[str]:
    if isinstance(value, list):
        return [str(item).strip() for item in value if str(item or "").strip()]
    if value is None:
        return []
    text = str(value).strip()
    return [text] if text else []


def _normalize_dialogue_turns(raw_turns: Any) -> list[dict[str, Any]]:
    turns = raw_turns if isinstance(raw_turns, list) else []
    normalized: list[dict[str, Any]] = []
    for index, turn in enumerate(turns):
        if not isinstance(turn, dict):
            continue
        turn_id = normalize_space(turn.get("turn_id") or turn.get("dia_id") or f"legacy:{index + 1}")
        text = normalize_space(turn.get("text"))
        if not turn_id or not text:
            continue
        normalized.append(
            {
                "turn_id": turn_id,
                "speaker": normalize_space(turn.get("speaker") or f"Speaker{(index % 2) + 1}"),
                "text": text,
            }
        )
    return normalized


def parse_dialogue_text_turns(dialogue_text: Any) -> list[dict[str, Any]]:
    """Parse bracketed dialogue text like `[D2:10] Caroline: ...` into turns."""
    turns: list[dict[str, Any]] = []
    current: dict[str, Any] | None = None
    for raw_line in str(dialogue_text or "").splitlines():
        line = raw_line.rstrip()
        match = DIALOGUE_TEXT_TURN_RE.match(line)
        if match:
            if current and normalize_space(current.get("text")):
                turns.append(
                    {
                        "turn_id": normalize_space(current.get("turn_id")),
                        "speaker": normalize_space(current.get("speaker")),
                        "text": normalize_space(current.get("text")),
                    }
                )
            current = {
                "turn_id": match.group(1).strip(),
                "speaker": match.group(2).strip(),
                "text": match.group(3).strip(),
            }
            continue
        if current is not None and normalize_space(line):
            current["text"] = normalize_space(f"{current.get('text', '')} {line.strip()}")
    if current and normalize_space(current.get("text")):
        turns.append(
            {
                "turn_id": normalize_space(current.get("turn_id")),
                "speaker": normalize_space(current.get("speaker")),
                "text": normalize_space(current.get("text")),
            }
        )
    return [turn for turn in turns if turn.get("turn_id") and turn.get("text")]


def parent_dialogue_turns_from_row(row: dict[str, Any]) -> tuple[list[dict[str, Any]], str]:
    dialogue = row.get("dialogue") if isinstance(row.get("dialogue"), dict) else {}
    dialogue_turns = _normalize_dialogue_turns(dialogue.get("turns") if isinstance(dialogue.get("turns"), list) else [])
    if dialogue_turns:
        return dialogue_turns, "dialogue.turns"
    expanded_turns = parse_dialogue_text_turns(row.get("expanded_dialogue_text"))
    if expanded_turns:
        return expanded_turns, "expanded_dialogue_text"
    new_turns = parse_dialogue_text_turns(row.get("new_dialogue_text"))
    if new_turns:
        return new_turns, "new_dialogue_text"
    final_turns = _normalize_dialogue_turns(row.get("final_dialogue") if isinstance(row.get("final_dialogue"), list) else [])
    if final_turns:
        return final_turns, "final_dialogue"
    return [], "fallback_empty"


def sanitize_internal_text(text: Any) -> str:
    """Convert internal/project-shaped text into dialogue-facing scenario language."""
    cleaned = normalize_space(text)
    if not cleaned:
        return ""
    for pattern, replacement in INTERNAL_TEXT_REPLACEMENTS:
        cleaned = pattern.sub(replacement, cleaned)
    qa_artifact = re.search(r"\bQ:\s*(.*?)\s*A:\s*(.+)$", cleaned, flags=re.IGNORECASE)
    if qa_artifact:
        q_text = normalize_space(qa_artifact.group(1)).rstrip(" ?")
        a_text = normalize_space(qa_artifact.group(2)).strip(" .")
        if q_text and a_text:
            cleaned = f"{q_text}: {a_text}"
    cleaned = cleaned.replace(" / ", " ")
    cleaned = re.sub(r"\s+([,.!?;:])", r"\1", cleaned)
    cleaned = re.sub(r"\s+", " ", cleaned).strip(" -:;,.")
    if not cleaned:
        cleaned = "The speaker discusses a real-world update."
    return cleaned[:1].upper() + cleaned[1:]


# Synthetic surface phrases that leak template artifacts into solver-visible text. Used only
# by easy-mode natural-phrasing and the QA-option display cleanup; deterministic scaffold
# alignment, markers, turn_ids, gold, and validators are NOT driven by this list.
EASY_SYNTHETIC_SURFACE_REPLACEMENTS = [
    (re.compile(r"\bthe\s+detail\s+for\s+the\s+detail\b", re.IGNORECASE), "the detail"),
    (re.compile(r"\bdetail\s+for\s+the\s+detail\b", re.IGNORECASE), "detail"),
    (re.compile(r"\bI\s+logged\s+state\s+update\s*\d*\b", re.IGNORECASE), "I noted"),
    (re.compile(r"\bI\s+logged\b", re.IGNORECASE), "I noted"),
    (re.compile(r"\bstate\s+update\s*\d*\b", re.IGNORECASE), "update"),
    (re.compile(r"\bscope\s+guard\b", re.IGNORECASE), "who can see it"),
    (re.compile(r"\brouting\s+gate\b", re.IGNORECASE), "next step"),
    (re.compile(r"\breview\s+stamp\b", re.IGNORECASE), "review"),
    (re.compile(r"\bevidence\s+window\b", re.IGNORECASE), "supporting point"),
    (re.compile(r"\bfinal\s+routing\b", re.IGNORECASE), "final decision"),
    (re.compile(r"\bmain\s+point,\s*final\s+routing\s+activated\b", re.IGNORECASE), "the final decision is set"),
    (re.compile(r"\bwhat\s+was\s+said\s+earlier\b", re.IGNORECASE), "the earlier part of the conversation"),
    (re.compile(r"\bkept\s+it\s+tied\s+to\s+that\s+the\s+part\s+of\s+the\s+conversation\b", re.IGNORECASE), "connected it to that earlier point"),
]


def _natural_surface_text(text: Any) -> str:
    """Easy-mode only: rewrite residual synthetic surface phrases into natural language.

    Operates on solver-visible text. Returns natural prose; does not touch markers, ids,
    gold, or alignment metadata.
    """
    cleaned = normalize_space(text)
    if not cleaned:
        return ""
    for pattern, replacement in EASY_SYNTHETIC_SURFACE_REPLACEMENTS:
        cleaned = pattern.sub(replacement, cleaned)
    # Collapse article/preposition doubling introduced by phrase substitution (e.g. "the the").
    cleaned = re.sub(r"\b(the|a|an|that|to|of)\s+\1\b", r"\1", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\s+([,.!?;:])", r"\1", cleaned)
    cleaned = re.sub(r"\s+", " ", cleaned).strip()
    if not cleaned:
        return normalize_space(text)
    return cleaned[:1].upper() + cleaned[1:]


def _has_synthetic_surface_phrase(text: Any) -> bool:
    value = normalize_space(text)
    if not value:
        return False
    return any(pattern.search(value) for pattern, _ in EASY_SYNTHETIC_SURFACE_REPLACEMENTS)


def _status_natural_suffix(status: str) -> str:
    return STATUS_NATURAL_SUFFIXES.get(status, "")


def _formal_status_suffix_surface(status: str) -> str:
    suffix = _status_natural_suffix(status)
    return sanitize_internal_text(suffix) if suffix else ""


def _formal_status_meaning(status: str) -> str:
    return {
        "active": "current child fact",
        "restored": "made current again by a later update",
        "outdated": "superseded by a later child update",
        "canceled": "withdrawn before taking effect",
        "expired": "past its validity window",
        "delayed_not_active": "scheduled but not yet in effect",
        "false": "explicitly corrected as untrue",
        "belief": "uncertain personal impression",
        "report": "unconfirmed secondhand report",
        "scope_limited": "restricted to an allowed audience",
    }.get(status, "child conversation update")


def _naturalize_claim_for_status(claim: str, status: str) -> str:
    natural = sanitize_internal_text(claim)
    suffix = _status_natural_suffix(status)
    if not suffix:
        return natural
    # Broad aliases such as "old", "only", or "report" can occur in entity
    # names or values without expressing the event's status.  A non-active
    # event is therefore considered status-bound only when the complete local
    # canonical suffix is already present.
    if normalize_text(suffix) not in normalize_text(natural):
        natural = normalize_space(f"{natural}. {suffix}")
    return sanitize_internal_text(natural)


# Semantic graph slots are machine-facing identifiers.  A canonical graph may
# retain them internally, but its dialogue evidence contract must be ordinary
# prose; otherwise the challenger copies ``access_scope`` / ``Mark this fact``
# into sidecars and the solver-facing alignment is neither natural nor stable.
_DIALOGUE_SLOT_SURFACE_ALIASES = {
    "access_scope": "access level",
    "membership_status": "membership status",
    "office_location": "office location",
    "appointment_date": "appointment date",
    "meeting_time": "meeting time",
    "causal_result": "outcome",
}


def _dialogue_slot_surface(slot: Any) -> str:
    raw = normalize_space(slot).replace("_", " ").replace("-", " ")
    key = normalize_text(raw).replace(" ", "_")
    surface = _DIALOGUE_SLOT_SURFACE_ALIASES.get(key, raw)
    return sanitize_internal_text(surface) or "detail"


_OWNED_RESOURCE_RE = re.compile(
    r"^\s*(?P<owner>.+?)\s*(?:['\N{RIGHT SINGLE QUOTATION MARK}]s|['\N{RIGHT SINGLE QUOTATION MARK}])\s+(?P<resource>.+?)\s*$",
    re.IGNORECASE,
)


def _split_visibility_owned_resource(entity: Any) -> tuple[str, str]:
    """Recover an explicitly encoded owner/resource pair without guessing.

    Legacy visibility graphs commonly put a possessive resource in ``entity``
    (for example, ``Nate's gaming room``).  That surface contains both typed
    fields and is safe to split.  A bare entity such as ``Archive`` does not
    identify its owner; callers keep owner empty and the pre-dialogue gate
    fails closed instead of inventing one.
    """

    surface = normalize_space(entity)
    match = _OWNED_RESOURCE_RE.fullmatch(surface)
    if match is None:
        return "", surface
    return normalize_space(match.group("owner")), normalize_space(
        match.group("resource")
    )


def _visibility_permission_projection(event: dict[str, Any]) -> dict[str, str]:
    """Project legacy scope fields into the typed visibility representation."""

    scope = event.get("scope") if isinstance(event.get("scope"), dict) else {}
    parsed_owner, parsed_resource = _split_visibility_owned_resource(
        event.get("entity")
    )
    explicit_owner = normalize_space(event.get("owner") or scope.get("owner"))
    owner = explicit_owner or parsed_owner
    explicit_resource = normalize_space(
        event.get("resource") or scope.get("resource")
    )
    resource = explicit_resource or parsed_resource
    return {
        "owner": owner,
        "resource": resource,
        "observer": normalize_space(
            event.get("observer") or scope.get("observer")
        ),
        "action": normalize_space(
            event.get("action")
            or event.get("permission")
            or scope.get("action")
            or scope.get("permission")
        ),
        "condition": normalize_space(
            event.get("condition") or scope.get("condition")
        ),
        "access_class": normalize_space(
            event.get("access_class")
            or scope.get("access_class")
            or event.get("value")
        ),
        "status": normalize_space(event.get("status")),
    }


def _visibility_permission_support_claim(typed: dict[str, Any]) -> str:
    """Render every typed permission component into one natural claim."""

    owner = sanitize_internal_text(typed.get("owner"))
    resource = sanitize_internal_text(typed.get("resource"))
    observer = sanitize_internal_text(typed.get("observer"))
    action = sanitize_internal_text(typed.get("action"))
    condition = sanitize_internal_text(typed.get("condition"))
    access_class = sanitize_internal_text(typed.get("access_class"))
    status = normalize_text(typed.get("status")).replace(" ", "_")
    if not all((owner, resource, observer, action, condition, access_class, status)):
        return ""
    possessive = f"{owner}'" if owner.casefold().endswith("s") else f"{owner}'s"
    claim = (
        f"{observer} may {action} {possessive} {access_class} {resource} "
        f"under the condition that {condition}."
    )
    status_suffix = {
        "active": "This permission is currently active.",
        "restored": "This permission is active again after being restored.",
    }.get(status) or _status_natural_suffix(status)
    if status_suffix:
        claim = normalize_space(f"{claim} {status_suffix}")
    return sanitize_internal_text(claim)


def _typed_membership_support_claim(typed: dict[str, Any]) -> str:
    entity = sanitize_internal_text(typed.get("entity")) or "The group"
    slot = _dialogue_slot_surface(typed.get("slot"))
    member = sanitize_internal_text(typed.get("member")) or "the candidate"
    set_id = sanitize_internal_text(typed.get("set_id")) or "the named set"
    condition = sanitize_internal_text(typed.get("condition")) or "the stated condition"
    included = typed.get("included") is True
    apostrophe = chr(39)
    possessive = (
        f"{entity}{apostrophe}"
        if entity.casefold().endswith("s")
        else f"{entity}{apostrophe}s"
    )
    membership_phrase = "is a member of" if included else "is not a member of"
    claim = (
        f"{possessive} {slot} includes the candidate {member}; "
        f"under the condition {condition}, {member} {membership_phrase} {set_id}."
    )
    status_suffix = _status_natural_suffix(
        normalize_text(typed.get("status")).replace(" ", "_")
    )
    if status_suffix:
        claim = normalize_space(f"{claim} {status_suffix}")
    return sanitize_internal_text(claim)


def _typed_cause_support_claim(typed: dict[str, Any]) -> str:
    cause_entity = sanitize_internal_text(typed.get("cause_entity")) or "The cause"
    cause_slot = _dialogue_slot_surface(typed.get("cause_slot"))
    cause_value = sanitize_internal_text(typed.get("cause_value")) or "the stated trigger"
    effect_entity = sanitize_internal_text(typed.get("effect_entity")) or "The effect"
    effect_slot = _dialogue_slot_surface(typed.get("effect_slot"))
    effect_value = sanitize_internal_text(typed.get("effect_value")) or "the stated outcome"
    apostrophe = chr(39)
    cause_possessive = (
        f"{cause_entity}{apostrophe}"
        if cause_entity.casefold().endswith("s")
        else f"{cause_entity}{apostrophe}s"
    )
    effect_possessive = (
        f"{effect_entity}{apostrophe}"
        if effect_entity.casefold().endswith("s")
        else f"{effect_entity}{apostrophe}s"
    )
    claim = (
        f"{cause_possessive} {cause_slot} is {cause_value}, and this causes "
        f"{effect_possessive} {effect_slot} to be {effect_value}."
    )
    condition = sanitize_internal_text(typed.get("condition"))
    if condition:
        claim = normalize_space(f"{claim} This applies under the condition {condition}.")
    status_suffix = _status_natural_suffix(
        normalize_text(typed.get("status")).replace(" ", "_")
    )
    if status_suffix:
        claim = normalize_space(f"{claim} {status_suffix}")
    return sanitize_internal_text(claim)


def semantic_event_dialogue_support_claim(
    entity: Any,
    slot: Any,
    value: Any,
    status: Any,
    *,
    typed_visibility: dict[str, Any] | None = None,
    typed_membership: dict[str, Any] | None = None,
    typed_cause: dict[str, Any] | None = None,
) -> str:
    """Render a semantic fact as a natural, validator-compatible dialogue claim.

    The result deliberately names the entity, ordinary-language slot, value,
    and any non-active status.  It is deterministic and uses no API call, so a
    fixed graph remains fixed while its dialogue-facing evidence surface stops
    leaking schema syntax.
    """
    if isinstance(typed_visibility, dict):
        visibility_claim = _visibility_permission_support_claim(typed_visibility)
        if visibility_claim:
            return visibility_claim
    if isinstance(typed_membership, dict):
        membership_claim = _typed_membership_support_claim(typed_membership)
        if membership_claim:
            return membership_claim
    if isinstance(typed_cause, dict):
        cause_claim = _typed_cause_support_claim(typed_cause)
        if cause_claim:
            return cause_claim

    entity_surface = sanitize_internal_text(entity) or "The person"
    slot_surface = _dialogue_slot_surface(slot)
    value_surface = sanitize_internal_text(value) or "the stated detail"
    status_key = normalize_text(status).replace(" ", "_") or "active"
    possessive = (
        f"{entity_surface}'" if entity_surface.casefold().endswith("s") else f"{entity_surface}'s"
    )
    subject = f"{possessive} {slot_surface}"
    templates = {
        "belief": f"{subject} may be {value_surface}, but the team is unsure whether that is true.",
        "report": f"Someone reported that {subject} is {value_surface}, but nobody has confirmed it.",
        "outdated": f"{subject} was once {value_surface}, but that information is outdated and no longer applies.",
        "canceled": f"A proposal listed {subject} as {value_surface}, but it was canceled before taking effect.",
        "expired": f"{subject} was listed as {value_surface}, but that information has expired.",
        "delayed_not_active": f"{subject} is set to {value_surface}, but it is delayed and not active yet.",
        "false": f"People said {subject} was {value_surface}, but that was incorrect.",
        "scope_limited": f"Only authorized people may know that {subject} is {value_surface}.",
        "restored": f"{subject} is {value_surface} again after being restored.",
    }
    return sanitize_internal_text(templates.get(status_key, f"{subject} is {value_surface}."))


def _solver_visible_text_items(row_or_turns: Any) -> list[tuple[str, str]]:
    if isinstance(row_or_turns, dict):
        items: list[tuple[str, str]] = []
        if isinstance(row_or_turns.get("dialogue"), dict):
            dialogue = row_or_turns["dialogue"]
        elif isinstance(row_or_turns.get("turns"), list):
            # Pre-QA dialogue validation passes the canonical dialogue object
            # directly as {"turns": [...]}; clean rows wrap the same object in
            # {"dialogue": ...}.  Scan both shapes under identical field names
            # so the early gate cannot silently inspect zero turns.
            dialogue = row_or_turns
        else:
            dialogue = {}
        for index, turn in enumerate(dialogue.get("turns") if isinstance(dialogue.get("turns"), list) else []):
            if isinstance(turn, dict):
                items.append((f"dialogue.turns[{index}].text", str(turn.get("text") or "")))
        if row_or_turns.get("expanded_dialogue_text") is not None:
            items.append(("expanded_dialogue_text", str(row_or_turns.get("expanded_dialogue_text") or "")))
        if row_or_turns.get("question") is not None:
            items.append(("question", str(row_or_turns.get("question") or "")))
        qa = row_or_turns.get("qa") if isinstance(row_or_turns.get("qa"), dict) else {}
        if qa.get("question") is not None:
            items.append(("qa.question", str(qa.get("question") or "")))
        for index, option in enumerate(qa.get("options") if isinstance(qa.get("options"), list) else []):
            if isinstance(option, dict) and option.get("text") is not None:
                items.append((f"qa.options[{index}].text", str(option.get("text") or "")))
        gold = qa.get("gold")
        if isinstance(gold, list):
            for index, item in enumerate(gold):
                if isinstance(item, str):
                    items.append((f"qa.gold[{index}]", item))
        elif isinstance(gold, str):
            items.append(("qa.gold", gold))
        for key in ("answer", "rationale", "instruction", "instructions"):
            value = qa.get(key)
            if isinstance(value, str):
                items.append((f"qa.{key}", value))
        return items
    turns = row_or_turns if isinstance(row_or_turns, list) else []
    return [
        (f"dialogue.turns[{index}].text", str(turn.get("text") or ""))
        for index, turn in enumerate(turns)
        if isinstance(turn, dict)
    ]


_CURRENT_STATE_DIALOGUE_DETERMINERS = frozenset(
    {"a", "an", "the", "this", "that", "their", "his", "her", "its", "our"}
)
_CURRENT_STATE_INTERNAL_TARGET_TOKENS = frozenset(
    {
        "anchor",
        "dependency",
        "edge",
        "event",
        "event_instance_id",
        "gate",
        "graph",
        "graph_update",
        "ledger",
        "marker",
        "node",
        "alignment_anchor",
        "required_for_dialogue",
        "schema",
        "slot",
        "state",
        "status",
        "timeline",
        "update",
        "version",
    }
)


def _benign_dialogue_current_state_of(
    field: str,
    text: str,
    match: re.Match[str],
) -> bool:
    """Allow ordinary domain prose without weakening QA/internal-artifact gates."""

    if not (
        field.startswith("dialogue.turns[")
        or field == "expanded_dialogue_text"
    ):
        return False
    suffix = text[match.end() :]
    target_match = re.match(r"\s+of\s+([^,.;:!?]+)", suffix, flags=re.IGNORECASE)
    if target_match is None:
        return False
    target_tokens = re.findall(r"[A-Za-z0-9_'-]+", target_match.group(1))
    while (
        target_tokens
        and target_tokens[0].casefold() in _CURRENT_STATE_DIALOGUE_DETERMINERS
    ):
        target_tokens.pop(0)
    if not target_tokens:
        return False
    first_target = re.sub(r"(?:'s|’s)$", "", target_tokens[0].casefold())
    if "_" in first_target:
        return False
    if first_target in _CURRENT_STATE_INTERNAL_TARGET_TOKENS:
        return False
    if re.fullmatch(
        r"(?:e\d+|(?:event|anchor|marker|slot|node|edge)-?\d+|r[23](?:-\d+)?|conv-\d+|stage\d+)",
        first_target,
        flags=re.IGNORECASE,
    ):
        return False
    return True


def meta_leak_details_from_solver_visible_text(row_or_turns: Any) -> dict[str, Any]:
    details: list[dict[str, Any]] = []
    counts: Counter[str] = Counter()
    field_counts: Counter[str] = Counter()
    for field, text in _solver_visible_text_items(row_or_turns):
        for name, pattern in META_LEAK_PATTERNS:
            matches = [
                match.group(0)
                for match in pattern.finditer(text)
                if not (
                    name == "current_state"
                    and _benign_dialogue_current_state_of(field, text, match)
                )
            ]
            if not matches:
                continue
            counts[name] += len(matches)
            field_counts[field] += len(matches)
            details.append(
                {
                    "field": field,
                    "term": name,
                    "matches": matches[:5],
                    "text_preview": text[:240],
                }
            )
    return {
        "meta_leak_count": sum(counts.values()),
        "banned_term_counts": dict(counts),
        "field_counts": dict(field_counts),
        "details": details,
        "matched_terms": sorted(counts),
    }


def assert_no_meta_leakage(row_or_turns: Any) -> tuple[bool, dict[str, Any]]:
    details = meta_leak_details_from_solver_visible_text(row_or_turns)
    return details["meta_leak_count"] == 0, details


def _strip_markers_and_known_anchors(text: Any, known_anchors: Iterable[str]) -> str:
    cleaned = normalize_space(GENERIC_MARKER_RE.sub(" ", str(text or "")))
    for anchor in known_anchors:
        anchor_text = str(anchor or "").strip()
        if anchor_text:
            cleaned = cleaned.replace(anchor_text, " ")
    return normalize_space(cleaned)


def _meta_clean_text(text: str) -> str:
    cleaned = normalize_space(text)
    for _ in range(5):
        ok, _details = assert_no_meta_leakage([{"text": cleaned}])
        if ok:
            return cleaned
        updated = sanitize_internal_text(cleaned)
        if updated == cleaned:
            break
        cleaned = updated
    return normalize_space(cleaned)


def solver_visible_parent_dialogue_turns(
    parent_dialogue_turns: list[dict[str, Any]],
    known_anchors: Iterable[str],
) -> list[dict[str, Any]]:
    clean_turns: list[dict[str, Any]] = []
    for index, turn in enumerate(parent_dialogue_turns):
        if not isinstance(turn, dict):
            continue
        text = _strip_markers_and_known_anchors(turn.get("text"), known_anchors)
        if not text:
            continue
        clean_turns.append(
            {
                "turn_id": normalize_space(turn.get("turn_id") or f"legacy:{index + 1}"),
                "speaker": normalize_space(turn.get("speaker") or f"Speaker{(index % 2) + 1}"),
                "text": _meta_clean_text(text),
            }
        )
    return clean_turns


def qa_dialogue_meta_counts(row: dict[str, Any]) -> dict[str, int]:
    details = meta_leak_details_from_solver_visible_text(row)
    qa_count = 0
    dialogue_count = 0
    for item in details.get("details") or []:
        field = str(item.get("field") or "")
        count = len(item.get("matches") or [])
        if field.startswith("qa.") or field == "question":
            qa_count += count
        elif field.startswith("dialogue.") or field == "expanded_dialogue_text":
            dialogue_count += count
    return {"qa_meta_leak_count": qa_count, "dialogue_meta_leak_count": dialogue_count}


def meta_leak_stats(rows: list[dict[str, Any]]) -> dict[str, Any]:
    total = 0
    counts: Counter[str] = Counter()
    for row in rows:
        ok, details = assert_no_meta_leakage(row)
        if ok:
            continue
        total += int(details.get("meta_leak_count") or 0)
        counts.update(details.get("banned_term_counts") or {})
    qa_count = 0
    dialogue_count = 0
    for row in rows:
        counts_by_area = qa_dialogue_meta_counts(row)
        qa_count += counts_by_area["qa_meta_leak_count"]
        dialogue_count += counts_by_area["dialogue_meta_leak_count"]
    return {
        "meta_leak_count": total,
        "solver_visible_meta_leak_count": total,
        "qa_meta_leak_count": qa_count,
        "dialogue_meta_leak_count": dialogue_count,
        "banned_term_counts": dict(counts),
    }


def _merge_counter_dict(target: dict[str, Any], source: dict[str, Any]) -> None:
    for key, value in (source or {}).items():
        target[key] = int(target.get(key) or 0) + int(value or 0)


def _merge_local_summary(global_summary: dict[str, Any], local: dict[str, Any]) -> None:
    """Additively merge a worker's local summary delta into the global summary.

    Integer counters are summed; nested dict counters (e.g. by_question_type, banned_term_counts)
    are merged key-wise. Non-additive scalars set by the driver (mode, floors) are left untouched.
    """
    skip_keys = {
        "native_curriculum_mode",
        "length_min_added_turns",
        "length_min_added_tokens",
        "length_guard_enabled",
        "min_length_delta_tokens",
        "length_guard_parent_baseline_tokens",
        "length_guard_effective_parent_tokens_mean",
        "length_guard_effective_delta_tokens_mean",
        "length_guard_baseline_mode",
        "length_guard_target_delta",
        "length_guard_fallback_used",
        "fallback_delta",
        "emergency_floor",
        "length_tokenizer_path",
        "length_token_count_mode",
        "easy_v2_planned_question_type_quota",
        "difficulty_plan_applied",
        "difficulty_plan_stage",
        "difficulty_plan_manual_policy_correction",
        "stage64_qa_repair_max_attempts",
    }
    for key, value in local.items():
        if key in skip_keys:
            continue
        if isinstance(value, dict):
            target = global_summary.get(key)
            if not isinstance(target, dict):
                target = {}
                global_summary[key] = target
            _merge_counter_dict(target, value)
        elif isinstance(value, bool):
            # bool is a subclass of int in Python.  Treat worker-owned flags as
            # logical facts, otherwise three attempts turn True into the bogus
            # summary value 3 (as observed in the n=1 smoke audit).
            global_summary[key] = bool(global_summary.get(key)) or value
        elif isinstance(value, (int, float)):
            base_val = global_summary.get(key)
            global_summary[key] = (base_val if isinstance(base_val, (int, float)) else 0) + value
        # strings / other: leave the driver-owned value in place



def _bump_summary_counter(summary: dict[str, Any], key: str, amount: int = 1) -> None:
    summary[key] = int(summary.get(key) or 0) + int(amount or 0)


def _bump_failure_reason(summary: dict[str, Any], reason: str) -> None:
    reason_key = normalize_space(reason) or "unknown"
    counts = summary.setdefault("api_failure_reason_counts", {})
    counts[reason_key] = int(counts.get(reason_key) or 0) + 1


def _api_meta_error_types(meta: dict[str, Any]) -> list[str]:
    error_types: list[str] = []
    for error in meta.get("errors") or meta.get("previous_errors") or []:
        if isinstance(error, dict) and normalize_space(error.get("error_type")):
            error_types.append(normalize_space(error.get("error_type")))
    if normalize_space(meta.get("error_type")):
        error_types.append(normalize_space(meta.get("error_type")))
    return error_types


def _api_meta_has_timeout(meta: dict[str, Any]) -> bool:
    for error_type in _api_meta_error_types(meta):
        if "timeout" in error_type.lower() or "timed_out" in error_type.lower():
            return True
    for error in meta.get("errors") or meta.get("previous_errors") or []:
        if isinstance(error, dict) and "timed out" in str(error.get("error") or "").lower():
            return True
    return False


def _api_meta_has_parse_failure(meta: dict[str, Any]) -> bool:
    parse_error_types = {"invalid_json", "missing_required_keys", "json_decode_error", "parse_error"}
    return any(error_type in parse_error_types for error_type in _api_meta_error_types(meta))


def _record_api_meta_retry_diagnostics(summary: dict[str, Any], meta: dict[str, Any]) -> None:
    if not isinstance(meta, dict):
        return
    usage = meta.get("usage") if isinstance(meta.get("usage"), dict) else {}
    for source_key, summary_key in (
        ("prompt_tokens", "api_usage_prompt_tokens"),
        ("completion_tokens", "api_usage_completion_tokens"),
        ("total_tokens", "api_usage_total_tokens"),
    ):
        _bump_summary_counter(summary, summary_key, int(usage.get(source_key) or 0))
    normalizer = meta.get("normalizer_diagnostics") if isinstance(meta.get("normalizer_diagnostics"), dict) else {}
    if meta.get("call_kind") == "api_graph_expansion":
        if normalizer.get("graph_json_normalizer_used"):
            _bump_summary_counter(summary, "graph_json_normalizer_used_count")
        if normalizer.get("graph_update_events_unwrap"):
            _bump_summary_counter(summary, "graph_update_events_unwrap_count")
        if normalizer.get("graph_json_normalizer_failure"):
            _bump_summary_counter(summary, "graph_json_normalizer_failure_count")
        if meta.get("used") and normalizer.get("graph_json_normalizer_used"):
            _bump_summary_counter(summary, "graph_reject_recovered_by_normalizer_count")
    if meta.get("call_kind") == "api_dialogue_expansion":
        if normalizer.get("dialogue_json_normalizer_used"):
            _bump_summary_counter(summary, "dialogue_json_normalizer_used_count")
        if normalizer.get("dialogue_json_block_extracted"):
            _bump_summary_counter(summary, "dialogue_json_block_extracted_count")
        if normalizer.get("dialogue_wrapper_unwrap"):
            _bump_summary_counter(summary, "dialogue_wrapper_unwrap_count")
        if normalizer.get("dialogue_json_normalizer_failure"):
            _bump_summary_counter(summary, "dialogue_json_normalizer_failure_count")
        if meta.get("used") and normalizer.get("dialogue_json_normalizer_used"):
            _bump_summary_counter(summary, "dialogue_reject_recovered_by_normalizer_count")
    if meta.get("call_kind") == "api_formal_segmented_dialogue":
        for record in meta.get("segment_records") or []:
            record_meta = (
                record.get("meta")
                if isinstance(record, dict) and isinstance(record.get("meta"), dict)
                else {}
            )
            if record_meta.get("temperature_override") is not None:
                _bump_summary_counter(
                    summary,
                    "formal_dialogue_retry_temperature_override_count",
                )
                if normalize_space(record_meta.get("diversity_retry_reason")):
                    _bump_summary_counter(
                        summary,
                        "formal_dialogue_diversity_temperature_override_count",
                    )
                structural_reason = normalize_space(
                    record_meta.get("structural_retry_reason")
                )
                if structural_reason:
                    _bump_summary_counter(
                        summary,
                        "formal_dialogue_structural_temperature_override_count",
                    )
                    structural_counts = summary.setdefault(
                        "formal_dialogue_structural_retry_reason_counts", {}
                    )
                    structural_counts[structural_reason] = int(
                        structural_counts.get(structural_reason) or 0
                    ) + 1
            if (
                int(record.get("segment_index") or 0)
                >= FORMAL_DIALOGUE_LATE_RETRY_START_SEGMENT_INDEX
                and int(record.get("segment_attempt") or 0)
                > FORMAL_DIALOGUE_MIN_SEGMENT_VALIDATION_ATTEMPTS
                and record.get("compiled_payload") is not None
            ):
                _bump_summary_counter(
                    summary,
                    "formal_dialogue_late_local_retry_count",
                )
            summary["formal_dialogue_forbidden_opening_prefix_count_max"] = max(
                int(
                    summary.get(
                        "formal_dialogue_forbidden_opening_prefix_count_max"
                    )
                    or 0
                ),
                len(record_meta.get("forbidden_opening_prefixes") or []),
            )
            validation = record.get("validation") if isinstance(record, dict) else None
            if not isinstance(validation, dict) or validation.get("pass") is True:
                continue
            reason = normalize_space(validation.get("reason"))
            counter_key = {
                "segment_exact_duplicate_turn": "formal_segment_exact_duplicate_reject_count",
                "frozen_prefix_turn_repeated": "formal_segment_exact_duplicate_reject_count",
                "segment_near_duplicate_turn": "formal_segment_near_duplicate_reject_count",
                "segment_phrase_containment_duplicate_turn": (
                    "formal_segment_phrase_containment_reject_count"
                ),
                "segment_opening_prefix_concentration": (
                    "formal_segment_opening_concentration_reject_count"
                ),
                "cumulative_opening_prefix_concentration": (
                    "formal_segment_opening_concentration_reject_count"
                ),
            }.get(reason)
            if counter_key:
                _bump_summary_counter(summary, counter_key)
            if reason == "segment_opening_prefix_concentration":
                _bump_summary_counter(
                    summary,
                    "formal_segment_opening_segment_scope_reject_count",
                )
            elif reason == "cumulative_opening_prefix_concentration":
                _bump_summary_counter(
                    summary,
                    "formal_segment_opening_cumulative_scope_reject_count",
                )
            opening_audit = validation.get("opening_diversity_audit")
            if isinstance(opening_audit, dict):
                rejected_prefixes = opening_audit.get("rejected_prefixes") or []
                _bump_summary_counter(
                    summary,
                    "formal_segment_opening_rejected_prefix_count",
                    len(rejected_prefixes),
                )
            audit = validation.get("turn_duplicate_audit")
            if isinstance(audit, dict):
                _bump_summary_counter(
                    summary,
                    "formal_segment_exact_duplicate_pair_reject_count",
                    int(audit.get("exact_duplicate_pair_count") or 0),
                )
                _bump_summary_counter(
                    summary,
                    "formal_segment_near_duplicate_pair_reject_count",
                    int(audit.get("near_duplicate_pair_count") or 0),
                )
                _bump_summary_counter(
                    summary,
                    "formal_segment_phrase_containment_pair_reject_count",
                    int(audit.get("phrase_containment_pair_count") or 0),
                )
    errors = [
        error
        for error in (meta.get("errors") or meta.get("previous_errors") or [])
        if isinstance(error, dict)
    ]
    if not errors and normalize_space(meta.get("error_type")):
        errors = [{"error_type": normalize_space(meta.get("error_type")), "error": meta.get("error")}]
    parse_error_types = {"invalid_json", "missing_required_keys", "json_decode_error", "parse_error"}
    for error in errors:
        error_type = normalize_space(error.get("error_type"))
        error_text = str(error.get("error") or "")
        if error_type in parse_error_types:
            _bump_summary_counter(summary, "parse_failure_count")
        if "timeout" in error_type.lower() or "timed_out" in error_type.lower() or "timed out" in error_text.lower():
            _bump_summary_counter(summary, "timeout_count")


def _record_query_conditioned_graph_diagnostics(summary: dict[str, Any], meta: dict[str, Any]) -> None:
    if not isinstance(meta, dict):
        return
    diag = meta.get("query_conditioned_graph_diagnostics")
    if not isinstance(diag, dict) or not diag.get("query_conditioned_graph_expansion"):
        return
    _bump_summary_counter(summary, "query_conditioned_graph_objective_created_count")
    if diag.get("pass"):
        _bump_summary_counter(summary, "query_conditioned_graph_plan_pass_count")
    else:
        _bump_summary_counter(summary, "query_conditioned_graph_plan_fail_count")
        reason = normalize_space(diag.get("failure_reason")) or "unknown"
        counts = summary.setdefault("query_conditioned_graph_plan_failure_reason", {})
        counts[reason] = int(counts.get(reason) or 0) + 1
    if normalize_space(diag.get("query_plan_type")):
        counts = summary.setdefault("query_conditioned_graph_plan_type", {})
        key = normalize_space(diag.get("query_plan_type"))
        counts[key] = int(counts.get(key) or 0) + 1
    _bump_summary_counter(summary, "query_conditioned_graph_event_count_sum", int(diag.get("event_count") or 0))
    _bump_summary_counter(summary, "query_conditioned_graph_active_event_count_sum", int(diag.get("active_event_count") or 0))
    _bump_summary_counter(summary, "query_conditioned_graph_scope_limited_event_count_sum", int(diag.get("scope_limited_event_count") or 0))
    _bump_summary_counter(summary, "query_conditioned_graph_invalidating_event_count_sum", int(diag.get("invalidating_event_count") or 0))
    _bump_summary_counter(summary, "query_conditioned_graph_natural_scope_limited_event_count_sum", int(diag.get("natural_scope_limited_event_count") or 0))
    _bump_summary_counter(summary, "query_conditioned_graph_natural_invalidating_event_count_sum", int(diag.get("natural_invalidating_event_count") or 0))
    _bump_summary_counter(summary, "query_conditioned_graph_placeholder_false_surface_count_sum", int(diag.get("placeholder_false_surface_count") or 0))
    _bump_summary_counter(summary, "query_conditioned_graph_single_choice_false_event_count_sum", int(diag.get("single_choice_false_event_count") or 0))
    _bump_summary_counter(summary, "query_conditioned_graph_single_choice_same_slot_false_count_sum", int(diag.get("single_choice_same_slot_false_count") or 0))
    _bump_summary_counter(summary, "query_conditioned_graph_single_choice_same_entity_false_count_sum", int(diag.get("single_choice_same_entity_false_count") or 0))


def _failure_reason_from_exception(exc: Exception, raw_record: dict[str, Any] | None = None) -> str:
    if raw_record and normalize_space(raw_record.get("final_reject_reason")):
        return normalize_space(raw_record.get("final_reject_reason"))
    message = str(exc).lower()
    if isinstance(exc, NativeGraphDialogueAnchorLeakReject) or "anchor leakage" in message:
        return "anchor_leak"
    if "dialogue alignment did not pass" in message:
        return "dialogue_alignment"
    if "length guard" in message or "too short" in message:
        return "length"
    if "typed_content_binding_exhausted" in message:
        return "truth_content_binding"
    if "valid json" in message or "invalid_json" in message or "missing_required_keys" in message:
        return "parse_failure"
    if "timeout" in message or "timed out" in message:
        return "timeout"
    if "api graph expansion failed" in message:
        return "api_graph"
    if "meta leakage" in message or "internal/project terms" in message:
        return "meta_leak"
    if "stage64 graph semantic quality failed" in message or "semantic_graph_v2 quality failed" in message:
        return "stage64_graph_quality"
    if "anti_shortcut" in message:
        return "base_validation_anti_shortcut"
    if "base validation" in message:
        return "base_validation"
    return type(exc).__name__


def _is_stage64_qa_repairable_error(exc: Exception) -> bool:
    if not isinstance(exc, NativeGraphDialogueReject):
        return False
    message = str(exc)
    if STAGE64_NON_REPAIRABLE_GRAPH_QUALITY_RE.search(message):
        return False
    return bool(STAGE64_QA_REPAIRABLE_RE.search(message))


def _visibility_gate_text_key(value: Any) -> str:
    return re.sub(
        r"[\W_]+",
        " ",
        normalize_space(value).casefold(),
        flags=re.UNICODE,
    ).strip()


def _visibility_typed_signature(event: dict[str, Any]) -> tuple[str, ...]:
    return tuple(
        _visibility_gate_text_key(event.get(field))
        for field in VISIBILITY_TYPED_FIELDS
    )


def normalized_visibility_pre_dialogue_gate(
    plan: dict[str, Any],
) -> dict[str, Any]:
    """Fail closed when typed visibility facts or their claims collapse.

    Only permission events participate.  The first resource event in the
    Stage64 visibility layout intentionally has no scope, while every scoped
    required event must expose one complete, flat typed representation.  A
    dialogue request is safe only when the required cardinality equals both
    the unique typed-signature cardinality and unique support-claim
    cardinality.
    """

    operation = normalize_space(plan.get("operation"))
    events = [
        event
        for event in (plan.get("events") or [])
        if isinstance(event, dict)
    ]
    permission_event_rows = [
        (index, event)
        for index, event in enumerate(events)
        if event.get("required_for_dialogue") is not False
        and (
            normalize_space(event.get("event_type"))
            == VISIBILITY_PERMISSION_EVENT_TYPE
            or isinstance(event.get("scope"), dict)
        )
    ]
    permission_events = [event for _index, event in permission_event_rows]
    applicable = operation == "visibility"
    diagnostics: dict[str, Any] = {
        "schema_version": VISIBILITY_PRE_DIALOGUE_GATE_VERSION,
        "applicable": applicable,
        "pass": True,
        "required_count": len(permission_events),
        "unique_typed_signature_count": 0,
        "unique_support_claim_count": 0,
        "issues": [],
    }
    if not applicable:
        return diagnostics

    issues: list[dict[str, Any]] = []
    if operation == "visibility" and not permission_events:
        issues.append(
            {
                "code": "visibility_required_permission_events_missing",
                "path": "$.events",
                "message": (
                    "A visibility plan must contain at least one required typed "
                    "visibility_permission event before dialogue generation."
                ),
            }
        )

    signature_to_ids: dict[tuple[str, ...], list[str]] = {}
    claim_to_ids: dict[str, list[str]] = {}
    canonical_slot_to_access_classes: dict[
        tuple[str, ...], dict[str, list[str]]
    ] = {}
    for index, event in permission_event_rows:
        event_id = normalize_space(
            event.get("event_instance_id") or event.get("event_id")
        ) or f"events[{index}]"
        path = f"$.events[{index}]"
        if normalize_space(event.get("event_type")) != VISIBILITY_PERMISSION_EVENT_TYPE:
            issues.append(
                {
                    "code": "visibility_permission_event_type_missing",
                    "path": f"{path}.event_type",
                    "message": (
                        "Every required scoped visibility fact must use "
                        "event_type='visibility_permission'."
                    ),
                    "details": {"event_id": event_id},
                }
            )

        missing_fields = [
            field
            for field in VISIBILITY_TYPED_FIELDS
            if not _visibility_gate_text_key(event.get(field))
        ]
        if missing_fields:
            issues.append(
                {
                    "code": "visibility_typed_fields_missing",
                    "path": path,
                    "message": (
                        "A required visibility permission must preserve every "
                        "typed owner/resource/observer/action/condition/"
                        "access_class/status field."
                    ),
                    "details": {
                        "event_id": event_id,
                        "missing_fields": missing_fields,
                    },
                }
            )

        scope = event.get("scope") if isinstance(event.get("scope"), dict) else {}
        legacy_expectations = {
            "observer": scope.get("observer"),
            "action": scope.get("action") or scope.get("permission"),
            "condition": scope.get("condition"),
            "access_class": event.get("value"),
            "status": event.get("status"),
        }
        mismatched_fields = [
            field
            for field, expected in legacy_expectations.items()
            if _visibility_gate_text_key(expected)
            != _visibility_gate_text_key(event.get(field))
        ]
        parsed_owner, parsed_resource = _split_visibility_owned_resource(
            event.get("entity")
        )
        if parsed_owner and (
            _visibility_gate_text_key(parsed_owner)
            != _visibility_gate_text_key(event.get("owner"))
        ):
            mismatched_fields.append("owner")
        if parsed_resource and parsed_owner and (
            _visibility_gate_text_key(parsed_resource)
            != _visibility_gate_text_key(event.get("resource"))
        ):
            mismatched_fields.append("resource")
        mismatched_fields = list(dict.fromkeys(mismatched_fields))
        if mismatched_fields:
            issues.append(
                {
                    "code": "visibility_typed_fields_disagree_with_graph",
                    "path": path,
                    "message": (
                        "Typed visibility fields must preserve, not overwrite, "
                        "the graph entity/value/status and scope semantics."
                    ),
                    "details": {
                        "event_id": event_id,
                        "mismatched_fields": mismatched_fields,
                    },
                }
            )

        signature = _visibility_typed_signature(event)
        signature_to_ids.setdefault(signature, []).append(event_id)
        canonical_slot = tuple(
            _visibility_gate_text_key(event.get(field))
            for field in VISIBILITY_TYPED_FIELDS
            if field != "access_class"
        )
        access_class_key = _visibility_gate_text_key(event.get("access_class"))
        canonical_slot_to_access_classes.setdefault(canonical_slot, {}).setdefault(
            access_class_key, []
        ).append(event_id)
        claim = normalize_space(
            event.get("dialogue_support_claim")
            or (
                event.get("alignment_hints", {}).get("support_claim")
                if isinstance(event.get("alignment_hints"), dict)
                else ""
            )
        )
        claim_key = _visibility_gate_text_key(claim)
        claim_to_ids.setdefault(claim_key, []).append(event_id)
        missing_claim_fields = [
            field
            for field in VISIBILITY_TYPED_FIELDS
            if field != "status"
            and _visibility_gate_text_key(event.get(field))
            and _visibility_gate_text_key(event.get(field)) not in claim_key
        ]
        if not claim_key or missing_claim_fields:
            issues.append(
                {
                    "code": "visibility_support_claim_missing_typed_semantics",
                    "path": f"{path}.dialogue_support_claim",
                    "message": (
                        "The dialogue support claim must verbalize the typed "
                        "visibility permission without dropping a scope field."
                    ),
                    "details": {
                        "event_id": event_id,
                        "missing_fields": missing_claim_fields,
                    },
                }
            )

    unique_signature_count = len(signature_to_ids)
    unique_claim_count = len(claim_to_ids)
    diagnostics["unique_typed_signature_count"] = unique_signature_count
    diagnostics["unique_support_claim_count"] = unique_claim_count
    required_count = len(permission_events)
    access_class_collisions = [
        {
            "event_ids": [
                event_id
                for event_ids in access_classes.values()
                for event_id in event_ids
            ],
            "access_classes": sorted(access_classes),
        }
        for access_classes in canonical_slot_to_access_classes.values()
        if len(access_classes) > 1
    ]
    if access_class_collisions:
        issues.append(
            {
                "code": "visibility_canonical_slot_access_class_collision",
                "path": "$.events",
                "message": (
                    "One canonical owner/resource/observer/action/condition/status "
                    "slot cannot carry mutually exclusive access_class values."
                ),
                "details": {"collisions": access_class_collisions},
            }
        )
    if not (
        required_count == unique_signature_count == unique_claim_count
    ):
        issues.append(
            {
                "code": "normalized_visibility_cardinality_collapse",
                "path": "$.events",
                "message": (
                    "Before a dialogue API call, required visibility count must "
                    "equal both unique typed-signature count and unique support-"
                    "claim count."
                ),
                "details": {
                    "required_count": required_count,
                    "unique_typed_signature_count": unique_signature_count,
                    "unique_support_claim_count": unique_claim_count,
                    "typed_signature_collisions": [
                        event_ids
                        for event_ids in signature_to_ids.values()
                        if len(event_ids) > 1
                    ],
                    "support_claim_collisions": [
                        event_ids
                        for event_ids in claim_to_ids.values()
                        if len(event_ids) > 1
                    ],
                },
            }
        )
    diagnostics["issues"] = issues
    diagnostics["pass"] = not issues
    return diagnostics


def require_normalized_visibility_pre_dialogue_gate(
    plan: dict[str, Any],
) -> dict[str, Any]:
    diagnostics = normalized_visibility_pre_dialogue_gate(plan)
    if diagnostics["pass"] is not True:
        raise NativeGraphDialogueReject(
            "normalized visibility collision gate failed before dialogue API: "
            f"{diagnostics['issues'][:6]}"
        )
    return diagnostics


def semantic_graph_plan_quality_issues(
    plan: dict[str, Any],
    qa_operation: str,
    stage64_target: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    issues: list[dict[str, Any]] = []
    for issue in semantic_graph_v2.validate_graph_delta(
        plan,
        operation=qa_operation,
        reasoning_target=stage64_target,
    ):
        issues.append({"reason": str(issue.get("code") or "semantic_graph_v2"), **issue})
    issues.extend(
        stage64_quality.graph_plan_quality_issues(
            plan,
            qa_operation,
            stage64_target,
        )
    )
    issues.extend(_stage64_reasoning_graph_target_issues(plan, stage64_target))
    visibility_gate = normalized_visibility_pre_dialogue_gate(plan)
    for issue in visibility_gate["issues"]:
        issues.append(
            {
                "reason": str(issue.get("code") or "visibility_pre_dialogue"),
                **issue,
            }
        )
    deduplicated: dict[tuple[str, str], dict[str, Any]] = {}
    for issue in issues:
        key = (str(issue.get("reason") or "unknown"), str(issue.get("path") or ""))
        deduplicated.setdefault(key, issue)
    return list(deduplicated.values())


def _temporal_generation_text_key(value: Any) -> str:
    return re.sub(r"[\W_]+", " ", str(value).casefold(), flags=re.UNICODE).strip()


def _temporal_generation_value_key(value: Any) -> str:
    if isinstance(value, str):
        return json.dumps(["string", _temporal_generation_text_key(value)], ensure_ascii=False)
    try:
        return json.dumps(
            [type(value).__name__, value],
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
    except (TypeError, ValueError):
        return f"<{type(value).__module__}.{type(value).__qualname__}>"


def _temporal_generation_values_equal(left: Any, right: Any) -> bool:
    if isinstance(left, str) and isinstance(right, str):
        return _temporal_generation_text_key(left) == _temporal_generation_text_key(right)
    return type(left) is type(right) and left == right


_STAGE64_DATE_TIME_SLOT_RE = re.compile(
    r"(?:^|[_\-\s])(date|time|deadline|schedule|appointment|calendar|hour|minute)(?:$|[_\-\s])",
    re.IGNORECASE,
)
_STAGE64_LOCATION_SCOPE_SLOT_RE = re.compile(
    r"(?:^|[_\-\s])(location|destination|address|scope|office|room|venue|site|region|zone|campus|route)(?:$|[_\-\s])",
    re.IGNORECASE,
)
_STAGE64_DATE_TIME_VALUE_RE = re.compile(
    r"(?:\b\d{4}[-/]\d{1,2}[-/]\d{1,2}\b|\b\d{1,2}:\d{2}\b|\b(?:january|february|march|april|may|june|july|august|september|october|november|december)\b)",
    re.IGNORECASE,
)


def _stage64_temporal_answer_type_requirement(preferred_answer_type: str) -> str:
    """Return a graph-level, machine-audited temporal value-type contract."""

    guidance = {
        "LocationOrScope": (
            "use a location/scope slot such as destination, office_location, or access_scope "
            "and concrete place/scope values; do not use dates, deadlines, or times"
        ),
        "DateOrTime": (
            "use a date/time slot such as appointment_date, deadline, or meeting_time "
            "and four concrete date/time values"
        ),
        "Event": "use an event/meeting/activity slot and four concrete event values",
        "ObjectOrCommonNoun": "use an object/document/item slot and four concrete object values",
        "AttributeValue": "use one semantic attribute slot and four concrete non-question attribute values",
    }
    return guidance.get(
        preferred_answer_type,
        "use one semantic slot and four concrete values compatible with the frozen preferred answer type",
    )


_STAGE64_PERSON_NAME_TOKEN_RE = re.compile(
    r"[^\W\d_]+(?:[-'][^\W\d_]+)*\.?",
    re.UNICODE,
)
_STAGE64_PERSON_NAME_PARTICLES = frozenset(
    {"al", "bin", "da", "de", "del", "der", "di", "du", "la", "le", "van", "von"}
)
_STAGE64_PERSON_SLOT_REQUIRED_TOKENS = frozenset(
    {
        "advisor", "adviser", "artist", "assignee", "author", "captain",
        "child", "coach", "colleague", "companion", "contact", "coordinator",
        "curator", "delegate", "director", "discoverer", "employee", "founder",
        "friend", "guest", "host", "leader", "manager", "member", "mentor",
        "name", "observer", "organizer", "owner", "parent", "participant",
        "partner", "person", "recipient", "relative", "resident", "sibling",
        "speaker", "spouse", "teacher", "winner",
    }
)
_STAGE64_PERSON_SLOT_FORBIDDEN_TOKENS = frozenset(
    {
        "address", "age", "amount", "appointment", "approval", "condition",
        "confirmation", "count", "date", "day", "deadline", "destination",
        "duration", "hour", "level", "location", "minute", "month", "number",
        "permission", "quantity", "result", "room", "route", "schedule", "scope",
        "score", "site", "state", "status", "time", "venue", "verification",
        "week", "year",
    }
)


def _stage64_person_answer_atom(value: Any) -> bool:
    """Return whether a Person answer is a short proper-name atom, not a clause."""

    if not isinstance(value, str):
        return False
    text = normalize_space(value)
    tokens = text.split()
    if not 1 <= len(tokens) <= 5:
        return False
    for token in tokens:
        if _STAGE64_PERSON_NAME_TOKEN_RE.fullmatch(token) is None:
            return False
        name_parts = re.split(r"[-']", token.rstrip("."))
        if any(
            not part
            or (
                not part[0].isupper()
                and part.casefold() not in _STAGE64_PERSON_NAME_PARTICLES
            )
            for part in name_parts
        ):
            return False
    return True


def _stage64_person_answer_slot(slot: Any) -> bool:
    """Return whether a slot denotes a person-valued semantic role."""

    normalized = re.sub(r"[\W]+", "_", normalize_space(slot).casefold()).strip("_")
    if not normalized:
        return False
    tokens = [token for token in normalized.split("_") if token]
    token_variants = set(tokens)
    token_variants.update(
        token[:-1] for token in tokens if len(token) > 3 and token.endswith("s")
    )
    if token_variants.intersection(_STAGE64_PERSON_SLOT_FORBIDDEN_TOKENS):
        return False
    return bool(
        token_variants.intersection(_STAGE64_PERSON_SLOT_REQUIRED_TOKENS)
        or normalized.endswith("_by")
    )


def _stage64_answer_slot_requirement(preferred_answer_type: str) -> str:
    if preferred_answer_type == "Person":
        return (
            "use a person-valued semantic relation slot such as discoverer, assigned_partner, mentor, host, owner, "
            "member, participant, contact, or *_by; never use a date/time, location, count, status, state, "
            "confirmation, permission, or condition slot"
        )
    return "use a semantic relation slot whose predicate is compatible with the frozen preferred answer type"


def _temporal_generation_preferred_answer_type_issue(
    primary_events: list[dict[str, Any]],
    stage64_target: dict[str, Any] | None,
) -> dict[str, Any] | None:
    """Reject high-confidence temporal date/location type conflicts pre-dialogue."""

    preferred_answer_type = normalize_space(
        (stage64_target or {}).get("preferred_answer_type")
        if isinstance(stage64_target, dict)
        else ""
    )
    if preferred_answer_type not in {"LocationOrScope", "DateOrTime"}:
        return None
    if not primary_events:
        return None
    slot = normalize_space(primary_events[0].get("slot"))
    values = [normalize_space(event.get("value")) for event in primary_events]
    is_date_slot = bool(_STAGE64_DATE_TIME_SLOT_RE.search(slot))
    is_location_slot = bool(_STAGE64_LOCATION_SCOPE_SLOT_RE.search(slot))
    date_value_count = sum(
        bool(_STAGE64_DATE_TIME_VALUE_RE.search(value)) for value in values
    )
    mismatch = (
        preferred_answer_type == "LocationOrScope"
        and (is_date_slot or date_value_count == len(values))
    ) or (
        preferred_answer_type == "DateOrTime"
        and is_location_slot
        and date_value_count == 0
    )
    if not mismatch:
        return None
    return {
        "code": "temporal_generation_layout_primary_answer_type_mismatch",
        "path": "$.events[0:4]",
        "message": (
            "The temporal primary chain is incompatible with the frozen "
            "preferred_answer_type and must be rebuilt before dialogue generation."
        ),
        "details": {
            "preferred_answer_type": preferred_answer_type,
            "slot": slot,
            "date_slot": is_date_slot,
            "location_scope_slot": is_location_slot,
            "date_like_value_count": date_value_count,
            "primary_event_ids": [
                _temporal_event_ref(event, index)
                for index, event in enumerate(primary_events)
            ],
        },
    }


def _temporal_event_ref(event: Any, index: int) -> str:
    if isinstance(event, dict) and normalize_space(event.get("event_id")):
        return normalize_space(event.get("event_id"))
    return f"events[{index}]"


def temporal_raw_generation_layout_issues(
    candidate: dict[str, Any],
    stage64_target: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    """Validate the stricter API-generation layout without mutating the graph.

    ``semantic_graph_v2`` intentionally accepts general 6-8 event temporal
    graphs.  The native challenger uses this narrower eight-role protocol to
    keep one answer chain and four context singletons unambiguous.  This gate is
    reject-only: it never chooses a chain, changes a status, or drops an event.
    """

    if not isinstance(candidate, dict) or candidate.get("operation") != "temporal_state_update":
        return []
    events = candidate.get("events")
    if not isinstance(events, list):
        return [
            {
                "code": "temporal_generation_layout_missing_events",
                "path": "$.events",
                "message": "Native temporal generation requires an eight-event array.",
            }
        ]

    issues: list[dict[str, Any]] = []
    if len(events) != 8:
        issues.append(
            {
                "code": "temporal_generation_layout_event_count",
                "path": "$.events",
                "message": "Native temporal generation requires exactly eight events in role order.",
                "details": {"expected": 8, "actual": len(events)},
            }
        )
    if len(events) < 8 or not all(isinstance(event, dict) for event in events[:8]):
        return issues

    primary = events[:4]
    context = events[4:8]
    primary_ids = [_temporal_event_ref(event, index) for index, event in enumerate(primary)]
    context_ids = [
        _temporal_event_ref(event, index)
        for index, event in enumerate(context, start=4)
    ]
    required_event_ids = [f"E{index}" for index in range(1, 9)]
    actual_event_ids = primary_ids + context_ids
    if actual_event_ids != required_event_ids:
        issues.append(
            {
                "code": "temporal_generation_layout_event_id_order",
                "path": "$.events",
                "message": "Native temporal generation requires event IDs E1 through E8 in exact array order.",
                "details": {
                    "expected": required_event_ids,
                    "actual": actual_event_ids,
                },
            }
        )

    if len(set(primary_ids)) != 4:
        issues.append(
            {
                "code": "temporal_generation_layout_primary_ids_not_unique",
                "path": "$.events[0:4]",
                "message": "The four primary temporal roles require four unique event_id values.",
                "details": {"event_ids": primary_ids},
            }
        )

    chain_entity = primary[0].get("entity")
    chain_slot = primary[0].get("slot")
    mismatched_primary_ids = [
        primary_ids[index]
        for index, event in enumerate(primary)
        if event.get("entity") != chain_entity or event.get("slot") != chain_slot
    ]
    if mismatched_primary_ids:
        issues.append(
            {
                "code": "temporal_generation_layout_primary_entity_slot_mismatch",
                "path": "$.events[0:4]",
                "message": "The first four events must use byte-for-byte identical entity and slot strings.",
                "details": {
                    "chain_entity": chain_entity,
                    "chain_slot": chain_slot,
                    "mismatched_event_ids": mismatched_primary_ids,
                },
            }
        )

    answer_type_issue = _temporal_generation_preferred_answer_type_issue(
        primary,
        stage64_target,
    )
    if answer_type_issue is not None:
        issues.append(answer_type_issue)

    value_to_ids: dict[str, list[str]] = {}
    for event_id, event in zip(primary_ids, primary):
        value_to_ids.setdefault(
            _temporal_generation_value_key(event.get("value")), []
        ).append(event_id)
    duplicate_value_event_ids = [
        event_ids for event_ids in value_to_ids.values() if len(event_ids) > 1
    ]
    if duplicate_value_event_ids:
        issues.append(
            {
                "code": "temporal_generation_layout_primary_value_cycle",
                "path": "$.events[0:4]",
                "message": "The four primary values must be semantically distinct; restore cycles are forbidden.",
                "details": {"duplicate_value_event_ids": duplicate_value_event_ids},
            }
        )

    anti_shortcut = bool(
        isinstance(stage64_target, dict)
        and all(field in stage64_target for field in STAGE64_REASONING_TARGET_FIELDS)
        and stage64_target.get("forbid_max_time_shortcut") is True
    )
    strategy = (
        str(stage64_target.get("hard_negative_strategy") or "")
        if anti_shortcut
        else ""
    )
    required_later_statuses = STAGE64_TEMPORAL_HARD_NEGATIVE_STATUSES.get(
        strategy, frozenset()
    )
    if anti_shortcut:
        active_indexes = [
            index
            for index, event in enumerate(primary)
            if event.get("status") in ACTIVE_STATUSES
        ]
        if len(active_indexes) != 1:
            issues.append(
                {
                    "code": "temporal_generation_layout_current_not_unique",
                    "path": "$.events[0:4]",
                    "message": "The anti-shortcut primary chain requires exactly one active/current event.",
                    "details": {"active_array_indexes": active_indexes},
                }
            )
        elif active_indexes[0] == 3:
            issues.append(
                {
                    "code": "temporal_generation_layout_current_is_max_time",
                    "path": "$.events[3].status",
                    "message": "The anti-shortcut current/gold event must occur before the maximum-time update.",
                    "details": {"event_id": primary_ids[3]},
                }
            )
        else:
            active_index = active_indexes[0]
            later = primary[active_index + 1 :]
            wrong_non_current_ids = [
                primary_ids[index]
                for index, event in enumerate(primary)
                if index != active_index
                and event.get("status") not in semantic_graph_v2.NON_ACTIVE_STATUSES
            ]
            if wrong_non_current_ids:
                issues.append(
                    {
                        "code": "temporal_generation_layout_non_current_not_invalid",
                        "path": "$.events[0:4]",
                        "message": "Every non-current primary event must use an explicit non-active status.",
                        "details": {"event_ids": wrong_non_current_ids},
                    }
                )
            matching_later_ids = [
                primary_ids[index]
                for index in range(active_index + 1, 4)
                if primary[index].get("status") in required_later_statuses
            ]
            if not required_later_statuses:
                issues.append(
                    {
                        "code": "temporal_generation_layout_unknown_hard_negative_strategy",
                        "path": "$.events[0:4]",
                        "message": "The temporal anti-shortcut target uses an unsupported hard-negative strategy.",
                        "details": {"hard_negative_strategy": strategy},
                    }
                )
            elif not matching_later_ids:
                issues.append(
                    {
                        "code": "temporal_generation_layout_missing_later_strategy_update",
                        "path": "$.events[0:4]",
                        "message": "A later same-slot invalid update must realize the target hard-negative strategy.",
                        "details": {
                            "hard_negative_strategy": strategy,
                            "required_later_statuses": sorted(required_later_statuses),
                        },
                    }
                )
    else:
        wrong_earlier_status_ids = [
            primary_ids[index]
            for index, event in enumerate(primary[:3])
            if event.get("status") in ACTIVE_STATUSES
        ]
        if wrong_earlier_status_ids:
            issues.append(
                {
                    "code": "temporal_generation_layout_earlier_primary_active",
                    "path": "$.events[0:3]",
                    "message": "The first three primary updates must be non-active.",
                    "details": {"event_ids": wrong_earlier_status_ids},
                }
            )
        if primary[3].get("status") != "active":
            issues.append(
                {
                    "code": "temporal_generation_layout_terminal_not_active",
                    "path": "$.events[3].status",
                    "message": "The terminal primary update must have status exactly 'active', never 'restored'.",
                    "details": {
                        "event_id": primary_ids[3],
                        "actual": primary[3].get("status"),
                        "expected": "active",
                    },
                }
            )

    if "previous_value" in primary[0]:
        issues.append(
            {
                "code": "temporal_generation_layout_initial_previous_value_present",
                "path": "$.events[0].previous_value",
                "message": "The initial primary update must omit previous_value, including null.",
                "details": {"event_id": primary_ids[0]},
            }
        )
    broken_links: list[dict[str, Any]] = []
    for index in range(1, 4):
        previous = primary[index - 1]
        current = primary[index]
        if "previous_value" not in current or not _temporal_generation_values_equal(
            current.get("previous_value"), previous.get("value")
        ):
            broken_links.append(
                {
                    "event_id": primary_ids[index],
                    "predecessor_event_id": primary_ids[index - 1],
                    "expected_previous_value": previous.get("value"),
                    "actual_previous_value": current.get("previous_value"),
                }
            )
    if broken_links:
        issues.append(
            {
                "code": "temporal_generation_layout_broken_previous_value",
                "path": "$.events[1:4]",
                "message": "Each primary update after the first must point to the immediately preceding value.",
                "details": {"broken_links": broken_links},
            }
        )

    required_dependency_map = {
        "E1": [],
        "E2": ["E1"],
        "E3": ["E2"],
        "E4": ["E3"],
        "E5": [],
        "E6": [],
        "E7": [],
        "E8": [],
    }
    actual_dependency_map = {
        event_id: (
            [normalize_space(item) for item in event.get("depends_on") or []]
            if isinstance(event.get("depends_on"), list)
            else []
        )
        for event_id, event in zip(actual_event_ids, events[:8])
    }
    if actual_dependency_map != required_dependency_map:
        issues.append(
            {
                "code": "temporal_generation_layout_dependency_map",
                "path": "$.events",
                "message": "The temporal chain and context roles must match the exact dependency map.",
                "details": {
                    "required_dependency_map": required_dependency_map,
                    "actual_dependency_map": actual_dependency_map,
                },
            }
        )

    wrong_time_roles = [
        {
            "event_id": _temporal_event_ref(event, index),
            "expected_time_index": index + 1,
            "actual_time_index": event.get("time_index"),
        }
        for index, event in enumerate(events[:8])
        if isinstance(event.get("time_index"), bool)
        or not isinstance(event.get("time_index"), int)
        or event.get("time_index") != index + 1
    ]
    if wrong_time_roles:
        issues.append(
            {
                "code": "temporal_generation_layout_time_index_role_mismatch",
                "path": "$.events",
                "message": "time_index must equal the event's one-based array role position from 1 through 8.",
                "details": {"mismatches": wrong_time_roles},
            }
        )

    chain_key = (
        _temporal_generation_text_key(chain_entity),
        _temporal_generation_text_key(chain_slot),
    )
    context_keys = [
        (
            _temporal_generation_text_key(event.get("entity")),
            _temporal_generation_text_key(event.get("slot")),
        )
        for event in context
    ]
    repeated_context_ids: list[str] = []
    seen_keys = {chain_key}
    for event_id, key in zip(context_ids, context_keys):
        if key in seen_keys:
            repeated_context_ids.append(event_id)
        seen_keys.add(key)
    if repeated_context_ids:
        issues.append(
            {
                "code": "temporal_generation_layout_context_not_singleton",
                "path": "$.events[4:8]",
                "message": "Every context event needs an entity+slot pair distinct from the chain and every other context event.",
                "details": {"event_ids": repeated_context_ids},
            }
        )
    context_previous_value_ids = [
        context_ids[index]
        for index, event in enumerate(context)
        if "previous_value" in event
    ]
    if context_previous_value_ids:
        issues.append(
            {
                "code": "temporal_generation_layout_context_previous_value_present",
                "path": "$.events[4:8]",
                "message": "Context singleton events must omit previous_value, including null.",
                "details": {"event_ids": context_previous_value_ids},
            }
        )
    return issues


def _comparison_generation_key(event: dict[str, Any]) -> tuple[str, int] | None:
    slot = event.get("slot")
    time_index = event.get("time_index")
    normalized_slot = _temporal_generation_text_key(slot)
    if (
        not normalized_slot
        or isinstance(time_index, bool)
        or not isinstance(time_index, int)
    ):
        return None
    return normalized_slot, time_index


def comparison_raw_generation_layout_issues(
    candidate: dict[str, Any],
    stage64_target: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    """Reject native comparison graphs that do not follow the fixed 2+6 roles.

    The general ``semantic_graph_v2`` contract intentionally continues to
    accept 6-8 event comparison graphs.  Native generation is narrower: the
    first two events are the sole numeric pair and the remaining six events
    use structurally unique slot/time keys.  This validator never rewrites an
    event, status, value, or ordering.
    """

    if not isinstance(candidate, dict) or candidate.get("operation") != "comparison":
        return []
    events = candidate.get("events")
    if not isinstance(events, list):
        return [
            {
                "code": "comparison_generation_layout_missing_events",
                "path": "$.events",
                "message": "Native comparison generation requires an eight-event array.",
            }
        ]

    issues: list[dict[str, Any]] = []
    if len(events) != 8:
        issues.append(
            {
                "code": "comparison_generation_layout_event_count",
                "path": "$.events",
                "message": "Native comparison generation requires exactly eight events in fixed role order.",
                "details": {"expected": 8, "actual": len(events)},
            }
        )
    if len(events) < 8:
        return issues
    non_object_indexes = [
        index for index, event in enumerate(events[:8]) if not isinstance(event, dict)
    ]
    if non_object_indexes:
        issues.append(
            {
                "code": "comparison_generation_layout_non_object_event",
                "path": "$.events",
                "message": "Every native comparison role must contain an event object.",
                "details": {"array_indexes": non_object_indexes},
            }
        )
        return issues

    primary = events[:2]
    context = events[2:8]
    target_aware = bool(
        isinstance(stage64_target, dict)
        and normalize_space(stage64_target.get("qa_operation")) == "comparison"
    )
    primary_ids = [_temporal_event_ref(event, index) for index, event in enumerate(primary)]
    context_ids = [
        _temporal_event_ref(event, index)
        for index, event in enumerate(context, start=2)
    ]

    primary_entities = [
        _temporal_generation_text_key(event.get("entity")) for event in primary
    ]
    if not all(primary_entities) or primary_entities[0] == primary_entities[1]:
        issues.append(
            {
                "code": "comparison_generation_layout_primary_entities",
                "path": "$.events[0:2]",
                "message": "The two primary roles require two different non-empty entities.",
                "details": {
                    "event_ids": primary_ids,
                    "normalized_entities": primary_entities,
                },
            }
        )

    primary_slots = [event.get("slot") for event in primary]
    primary_keys = [_comparison_generation_key(event) for event in primary]
    primary_key = primary_keys[0]
    if (
        primary_key is None
        or primary_keys[1] is None
        or primary_key != primary_keys[1]
        or not isinstance(primary_slots[0], str)
        or not primary_slots[0].strip()
        or primary_slots[0] != primary_slots[1]
    ):
        issues.append(
            {
                "code": "comparison_generation_layout_primary_key",
                "path": "$.events[0:2]",
                "message": "The primary roles require one byte-for-byte identical non-empty slot and integer time_index.",
                "details": {
                    "event_ids": primary_ids,
                    "slots": primary_slots,
                    "keys": [list(key) if key is not None else None for key in primary_keys],
                },
            }
        )

    wrong_primary_status_ids = [
        primary_ids[index]
        for index, event in enumerate(primary)
        if event.get("status") != "active"
    ]
    if wrong_primary_status_ids:
        issues.append(
            {
                "code": "comparison_generation_layout_primary_status",
                "path": "$.events[0:2]",
                "message": "Both primary comparison events must have status exactly 'active'.",
                "details": {"event_ids": wrong_primary_status_ids},
            }
        )

    primary_values = [event.get("value") for event in primary]
    if (
        not all(isinstance(value, int) and not isinstance(value, bool) for value in primary_values)
        or primary_values[0] == primary_values[1]
    ):
        issues.append(
            {
                "code": "comparison_generation_layout_primary_values",
                "path": "$.events[0:2]",
                "message": "The primary comparison values must be two distinct JSON integers.",
                "details": {"event_ids": primary_ids, "values": primary_values},
            }
        )

    context_keys = [_comparison_generation_key(event) for event in context]
    invalid_context_ids = [
        context_ids[index] for index, key in enumerate(context_keys) if key is None
    ]
    if invalid_context_ids:
        issues.append(
            {
                "code": "comparison_generation_layout_context_invalid_key",
                "path": "$.events[2:8]",
                "message": "Every context role requires a non-empty slot and integer time_index.",
                "details": {"event_ids": invalid_context_ids},
            }
        )

    primary_collision_ids = [
        context_ids[index]
        for index, key in enumerate(context_keys)
        if key is not None and primary_key is not None and key == primary_key
    ]
    if primary_collision_ids:
        issues.append(
            {
                "code": "comparison_generation_layout_context_primary_key_collision",
                "path": "$.events[2:8]",
                "message": "No context event may reuse the primary normalized slot/time_index key.",
                "details": {
                    "primary_event_ids": primary_ids,
                    "primary_key": list(primary_key) if primary_key is not None else None,
                    "context_event_ids": primary_collision_ids,
                },
            }
        )

    context_ids_by_key: dict[tuple[str, int], list[str]] = {}
    for event_id, key in zip(context_ids, context_keys):
        if key is not None:
            context_ids_by_key.setdefault(key, []).append(event_id)
    allowed_contrast_key = (
        context_keys[0]
        if target_aware
        and len(context_keys) >= 2
        and context_keys[0] is not None
        and context_keys[0] == context_keys[1]
        else None
    )
    duplicate_context_keys = [
        {"key": list(key), "event_ids": event_ids}
        for key, event_ids in context_ids_by_key.items()
        if len(event_ids) > 1
        and not (
            key == allowed_contrast_key
            and event_ids == context_ids[:2]
            and len(event_ids) == 2
        )
    ]
    if duplicate_context_keys:
        issues.append(
            {
                "code": "comparison_generation_layout_context_key_collision",
                "path": "$.events[2:8]",
                "message": "The six context normalized slot/time_index keys must be pairwise distinct.",
                "details": {"collisions": duplicate_context_keys},
            }
        )
    return issues


def count_raw_generation_layout_issues(
    candidate: dict[str, Any],
) -> list[dict[str, Any]]:
    """Reject native count graphs that do not follow the fixed 4+4 roles.

    The general ``semantic_graph_v2`` contract intentionally accepts balanced
    six-to-eight-member sets. Native generation is narrower so retries have a
    deterministic target: eight distinct members of one exact semantic set,
    with four included roles followed by four excluded roles. This validator
    is reject-only and never changes a member value or truth label.
    """

    if not isinstance(candidate, dict) or candidate.get("operation") != "count":
        return []
    events = candidate.get("events")
    if not isinstance(events, list):
        return [
            {
                "code": "count_generation_layout_missing_events",
                "path": "$.events",
                "message": "Native count generation requires an eight-event array.",
            }
        ]

    issues: list[dict[str, Any]] = []
    if len(events) != 8:
        issues.append(
            {
                "code": "count_generation_layout_event_count",
                "path": "$.events",
                "message": "Native count generation requires exactly eight events in fixed role order.",
                "details": {"expected": 8, "actual": len(events)},
            }
        )
    if len(events) < 8:
        return issues
    non_object_indexes = [
        index for index, event in enumerate(events[:8]) if not isinstance(event, dict)
    ]
    if non_object_indexes:
        issues.append(
            {
                "code": "count_generation_layout_non_object_event",
                "path": "$.events",
                "message": "Every native count role must contain an event object.",
                "details": {"array_indexes": non_object_indexes},
            }
        )
        return issues

    role_events = events[:8]
    event_ids = [
        _temporal_event_ref(event, index)
        for index, event in enumerate(role_events)
    ]
    invalid_membership_ids: list[str] = []
    memberships: list[dict[str, Any] | None] = []
    for event_id, event in zip(event_ids, role_events):
        membership = event.get("set_membership")
        if (
            not isinstance(membership, dict)
            or not isinstance(membership.get("set_id"), str)
            or not membership.get("set_id").strip()
            or not isinstance(membership.get("included"), bool)
        ):
            invalid_membership_ids.append(event_id)
            memberships.append(None)
        else:
            memberships.append(membership)
    if invalid_membership_ids:
        issues.append(
            {
                "code": "count_generation_layout_invalid_membership",
                "path": "$.events",
                "message": "Every count role requires set_membership with a non-empty string set_id and boolean included.",
                "details": {"event_ids": invalid_membership_ids},
            }
        )

    first_membership = memberships[0]
    expected_set_id = first_membership.get("set_id") if first_membership else None
    expected_entity = role_events[0].get("entity")
    expected_slot = role_events[0].get("slot")
    invalid_dimension_ids = [
        event_ids[index]
        for index, (event, membership) in enumerate(zip(role_events, memberships))
        if (
            membership is None
            or not isinstance(event.get("entity"), str)
            or not event.get("entity").strip()
            or not isinstance(event.get("slot"), str)
            or not event.get("slot").strip()
            or membership.get("set_id") != expected_set_id
            or event.get("entity") != expected_entity
            or event.get("slot") != expected_slot
        )
    ]
    if invalid_dimension_ids:
        issues.append(
            {
                "code": "count_generation_layout_candidate_dimensions",
                "path": "$.events",
                "message": "All eight roles must use one byte-for-byte identical non-empty set_id, entity, and slot.",
                "details": {
                    "expected_set_id": expected_set_id,
                    "expected_entity": expected_entity,
                    "expected_slot": expected_slot,
                    "mismatched_event_ids": invalid_dimension_ids,
                },
            }
        )

    value_to_ids: dict[str, list[str]] = {}
    for event_id, event in zip(event_ids, role_events):
        value_to_ids.setdefault(
            _temporal_generation_value_key(event.get("value")), []
        ).append(event_id)
    duplicate_value_groups = [
        {"normalized_value_key": value_key, "event_ids": duplicate_ids}
        for value_key, duplicate_ids in value_to_ids.items()
        if len(duplicate_ids) > 1
    ]
    if duplicate_value_groups:
        issues.append(
            {
                "code": "count_generation_layout_duplicate_member_values",
                "path": "$.events",
                "message": "All eight count member values must be pairwise distinct after normalization.",
                "details": {"duplicate_groups": duplicate_value_groups},
            }
        )

    expected_included = [True, True, True, True, False, False, False, False]
    inclusion_mismatches = [
        {
            "event_id": event_ids[index],
            "array_index": index,
            "expected_included": expected,
            "actual_included": (
                memberships[index].get("included")
                if memberships[index] is not None
                else None
            ),
        }
        for index, expected in enumerate(expected_included)
        if memberships[index] is None
        or memberships[index].get("included") is not expected
    ]
    if inclusion_mismatches:
        issues.append(
            {
                "code": "count_generation_layout_inclusion_roles",
                "path": "$.events",
                "message": "events[0:4] must be included=true and events[4:8] must be included=false.",
                "details": {"mismatches": inclusion_mismatches},
            }
        )
    return issues


def _semantic_retry_canonical_sha256(value: Any) -> str:
    try:
        payload = json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )
    except (TypeError, ValueError):
        payload = repr(value)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _semantic_retry_machine_payload(value: Any) -> Any:
    """Remove response prose before comparing two invalid graph attempts."""

    if isinstance(value, dict) and isinstance(value.get("events"), list):
        return sanitize_invalid_graph_for_semantic_retry(value)
    return value


def _semantic_retry_repetition_diagnostic(
    history: list[dict[str, Any]],
) -> dict[str, Any] | None:
    """Detect two machine-equivalent invalid results before another API call."""

    if len(history) < 2:
        return None
    previous, current = history[-2:]
    previous_raw_payload = previous.get("raw_payload")
    current_raw_payload = current.get("raw_payload")
    previous_payload_hash = _semantic_retry_canonical_sha256(
        _semantic_retry_machine_payload(previous_raw_payload)
    )
    current_payload_hash = _semantic_retry_canonical_sha256(
        _semantic_retry_machine_payload(current_raw_payload)
    )
    previous_issues_hash = _semantic_retry_canonical_sha256(previous.get("issues") or [])
    current_issues_hash = _semantic_retry_canonical_sha256(current.get("issues") or [])
    if (
        previous_payload_hash != current_payload_hash
        or previous_issues_hash != current_issues_hash
    ):
        return None
    return {
        "triggered": True,
        "reason": "consecutive_machine_equivalent_invalid_semantic_payload",
        "consecutive_repeat_count": 2,
        "payload_sha256": current_payload_hash,
        "payload_hash_basis": "sanitized_machine_fields",
        "raw_payload_sha256": _semantic_retry_canonical_sha256(current_raw_payload),
        "issues_sha256": current_issues_hash,
        "observed_semantic_attempts": [
            previous.get("semantic_attempt"),
            current.get("semantic_attempt"),
        ],
        "prevented_next_semantic_attempt": int(current.get("semantic_attempt") or len(history)) + 1,
    }


def temporal_retry_candidate_chain_diagnostics(
    events: Any,
) -> list[dict[str, Any]]:
    """Expose errors hidden by the core validator's multiple-chain short circuit."""

    if not isinstance(events, list):
        return []
    grouped: dict[tuple[str, str], list[tuple[int, dict[str, Any]]]] = {}
    for index, event in enumerate(events):
        if not isinstance(event, dict):
            continue
        entity = _temporal_generation_text_key(event.get("entity"))
        slot = _temporal_generation_text_key(event.get("slot"))
        if entity and slot:
            grouped.setdefault((entity, slot), []).append((index, event))

    diagnostics: list[dict[str, Any]] = []
    for (entity, slot), indexed_group in grouped.items():
        if len(indexed_group) < 3:
            continue
        ordered = sorted(
            indexed_group,
            key=lambda item: (
                item[1].get("time_index")
                if isinstance(item[1].get("time_index"), int)
                and not isinstance(item[1].get("time_index"), bool)
                else 10**9,
                item[0],
            ),
        )
        event_ids = [_temporal_event_ref(event, index) for index, event in ordered]
        value_to_ids: dict[str, list[str]] = {}
        for event_id, (_index, event) in zip(event_ids, ordered):
            value_to_ids.setdefault(
                _temporal_generation_value_key(event.get("value")), []
            ).append(event_id)
        duplicate_value_event_ids = [
            ids for ids in value_to_ids.values() if len(ids) > 1
        ]
        current_event_ids = [
            event_id
            for event_id, (_index, event) in zip(event_ids, ordered)
            if event.get("status") in ACTIVE_STATUSES
        ]
        restored_event_ids = [
            event_id
            for event_id, (_index, event) in zip(event_ids, ordered)
            if event.get("status") == "restored"
        ]
        earlier_active_event_ids = [
            event_ids[index]
            for index, (_event_index, event) in enumerate(ordered[:-1])
            if event.get("status") in ACTIVE_STATUSES
        ]
        broken_links: list[dict[str, Any]] = []
        for order_index in range(1, len(ordered)):
            previous = ordered[order_index - 1][1]
            current = ordered[order_index][1]
            if "previous_value" not in current or not _temporal_generation_values_equal(
                current.get("previous_value"), previous.get("value")
            ):
                broken_links.append(
                    {
                        "event_id": event_ids[order_index],
                        "predecessor_event_id": event_ids[order_index - 1],
                        "expected_previous_value": previous.get("value"),
                        "actual_previous_value": current.get("previous_value"),
                    }
                )
        machine_failures: list[str] = []
        if duplicate_value_event_ids:
            machine_failures.append("duplicate_or_cycle_value")
        if len(current_event_ids) != 1:
            machine_failures.append("current_state_count_not_one")
        elif current_event_ids[0] != event_ids[-1]:
            machine_failures.append("current_state_not_terminal")
        if earlier_active_event_ids:
            machine_failures.append("earlier_event_active")
        if restored_event_ids:
            machine_failures.append("restored_status_forbidden_by_native_layout")
        if broken_links:
            machine_failures.append("broken_previous_value_link")
        diagnostics.append(
            {
                "entity": entity,
                "slot": slot,
                "event_ids": event_ids,
                "event_count": len(event_ids),
                "duplicate_value_event_ids": duplicate_value_event_ids,
                "current_event_ids": current_event_ids,
                "restored_event_ids": restored_event_ids,
                "earlier_active_event_ids": earlier_active_event_ids,
                "terminal_event_id": event_ids[-1],
                "broken_previous_value_links": broken_links,
                "machine_failures": machine_failures,
            }
        )
    return diagnostics


def _final_dialogue_reject_reason(
    retry_context: dict[str, Any] | None,
    alignment_result: dict[str, Any] | None,
) -> str:
    if isinstance(retry_context, dict):
        previous_error = normalize_space(retry_context.get("previous_error")).lower()
        if "valid json" in previous_error:
            meta = retry_context.get("dialogue_meta") if isinstance(retry_context.get("dialogue_meta"), dict) else {}
            if _api_meta_has_timeout(meta):
                return "timeout"
            if _api_meta_has_parse_failure(meta):
                return "parse_failure"
            return "api_dialogue"
        if "length guard" in previous_error:
            return "length"
        if "internal/project terms" in previous_error:
            return "meta_leak"
    if isinstance(alignment_result, dict):
        return "dialogue_alignment"
    return "dialogue_alignment"


def write_json(path: str | Path, payload: Any) -> None:
    output = Path(path)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def write_jsonl(path: str | Path, rows: Iterable[dict[str, Any]]) -> None:
    output = Path(path)
    output.parent.mkdir(parents=True, exist_ok=True)
    with output.open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, ensure_ascii=False) + "\n")


def read_jsonl_if_exists(path: str | Path) -> list[dict[str, Any]]:
    """Read valid JSONL rows, retaining a complete prefix after an interrupted append."""
    candidate = Path(path)
    if not candidate.exists() or candidate.stat().st_size == 0:
        return []
    rows: list[dict[str, Any]] = []
    try:
        with candidate.open("r", encoding="utf-8") as handle:
            for line in handle:
                line = line.strip()
                if not line:
                    continue
                try:
                    payload = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if isinstance(payload, dict):
                    rows.append(payload)
    except OSError:
        return rows
    return rows


def _audit_sample_id(row: dict[str, Any], artifact: str) -> str:
    if artifact == "marked":
        clean_sample = row.get("clean_sample") if isinstance(row.get("clean_sample"), dict) else {}
        return normalize_space(clean_sample.get("sample_id"))
    if artifact == "raw" and row.get("accepted") is True:
        return normalize_space(row.get("sample_id"))
    return ""


def _audit_record_key(row: dict[str, Any], artifact: str) -> str:
    """Return a stable resume key without conflating separate failed API attempts."""
    sample_id = _audit_sample_id(row, artifact)
    if sample_id:
        return f"{artifact}:accepted:{sample_id}"
    return f"{artifact}:payload:{stable_hash(row, length=40)}"


def _dedupe_audit_rows(
    rows: Iterable[dict[str, Any]],
    artifact: str,
) -> tuple[list[dict[str, Any]], set[str], int]:
    unique: list[dict[str, Any]] = []
    seen: set[str] = set()
    duplicate_count = 0
    for row in rows:
        key = _audit_record_key(row, artifact)
        if key in seen:
            duplicate_count += 1
            continue
        seen.add(key)
        unique.append(row)
    return unique, seen, duplicate_count


def _append_unique_audit_row(
    rows: list[dict[str, Any]],
    seen: set[str],
    row: dict[str, Any],
    artifact: str,
) -> bool:
    key = _audit_record_key(row, artifact)
    if key in seen:
        return False
    seen.add(key)
    rows.append(row)
    return True


def _read_valid_audit_jsonl(path: Path) -> tuple[list[dict[str, Any]], int]:
    """Keep valid JSONL rows when an interrupted full-file checkpoint leaves a partial line."""
    if not path.exists() or path.stat().st_size == 0:
        return [], 0
    rows: list[dict[str, Any]] = []
    invalid_row_count = 0
    try:
        with path.open("r", encoding="utf-8") as handle:
            for line in handle:
                line = line.strip()
                if not line:
                    continue
                try:
                    payload = json.loads(line)
                except json.JSONDecodeError:
                    invalid_row_count += 1
                    continue
                if isinstance(payload, dict):
                    rows.append(payload)
                else:
                    invalid_row_count += 1
    except OSError:
        return [], 1
    return rows, invalid_row_count


def _load_resume_audit_artifacts(
    output: Path,
    resumed_clean_samples: list[dict[str, Any]],
) -> tuple[
    list[dict[str, Any]],
    list[dict[str, Any]],
    list[dict[str, Any]],
    dict[str, Any],
]:
    """Load persisted generation audits only; missing records are reported, not reconstructed."""
    marked_file_rows, marked_invalid_count = _read_valid_audit_jsonl(output / "marked_samples.jsonl")
    validated_file_rows, validated_invalid_count = _read_valid_audit_jsonl(
        output / "graph_conditioned_api_dialogue_validated.jsonl"
    )
    raw_file_rows, raw_invalid_count = _read_valid_audit_jsonl(
        output / "graph_conditioned_api_dialogue_raw.jsonl"
    )
    reject_file_rows, reject_invalid_count = _read_valid_audit_jsonl(
        output / "graph_conditioned_api_dialogue_rejects.jsonl"
    )

    marked_samples, _, marked_duplicate_count = _dedupe_audit_rows(
        [*marked_file_rows, *validated_file_rows],
        "marked",
    )
    raw_records, _, raw_duplicate_count = _dedupe_audit_rows(raw_file_rows, "raw")
    rejects, _, reject_duplicate_count = _dedupe_audit_rows(reject_file_rows, "reject")

    clean_ids = {
        normalize_space(row.get("sample_id"))
        for row in resumed_clean_samples
        if normalize_space(row.get("sample_id"))
    }
    marked_ids = {
        sample_id
        for row in marked_samples
        if (sample_id := _audit_sample_id(row, "marked"))
    }
    accepted_raw_ids = {
        sample_id
        for row in raw_records
        if (sample_id := _audit_sample_id(row, "raw"))
    }
    diagnostics = {
        "resume_marked_file_row_count": len(marked_file_rows),
        "resume_marked_file_invalid_row_count": marked_invalid_count,
        "resume_validated_file_row_count": len(validated_file_rows),
        "resume_validated_file_invalid_row_count": validated_invalid_count,
        "resume_marked_loaded_count": len(marked_samples),
        "resume_marked_duplicate_row_count": marked_duplicate_count,
        "resume_raw_file_row_count": len(raw_file_rows),
        "resume_raw_file_invalid_row_count": raw_invalid_count,
        "resume_raw_loaded_count": len(raw_records),
        "resume_raw_duplicate_row_count": raw_duplicate_count,
        "resume_reject_file_row_count": len(reject_file_rows),
        "resume_reject_file_invalid_row_count": reject_invalid_count,
        "resume_reject_loaded_count": len(rejects),
        "resume_reject_duplicate_row_count": reject_duplicate_count,
        "resume_clean_without_marked_count": len(clean_ids - marked_ids),
        "resume_clean_without_accepted_raw_count": len(clean_ids - accepted_raw_ids),
        "resume_marked_without_clean_count": len(marked_ids - clean_ids),
        "resume_accepted_raw_without_clean_count": len(accepted_raw_ids - clean_ids),
        "resume_audit_reconstructed_count": 0,
    }
    return marked_samples, raw_records, rejects, diagnostics


def append_jsonl_line(path: str | Path, row: dict[str, Any]) -> None:
    """Crash-safe single-row append used to checkpoint each accepted sample."""
    output = Path(path)
    output.parent.mkdir(parents=True, exist_ok=True)
    with output.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(row, ensure_ascii=False) + "\n")
        handle.flush()


def write_json_atomic(path: str | Path, payload: Any) -> None:
    output = Path(path)
    output.parent.mkdir(parents=True, exist_ok=True)
    tmp = output.with_name(f".{output.name}.{os.getpid()}.{time.time_ns()}.tmp")
    tmp.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    tmp.replace(output)



def dialogue_turns_from_row(row: dict[str, Any]) -> list[dict[str, Any]]:
    turns, _source = parent_dialogue_turns_from_row(row)
    return turns


def turn_text_by_id(row: dict[str, Any]) -> dict[str, str]:
    return {str(turn["turn_id"]): str(turn["text"]) for turn in dialogue_turns_from_row(row)}


def item_text(item: dict[str, Any]) -> str:
    for key in (
        "value",
        "to",
        "restored_state",
        "cancelled_state",
        "invalidated_statement",
        "final_true_state",
        "planned_state",
        "activation_state",
        "from",
        "text",
    ):
        text = normalize_space(item.get(key))
        if text:
            return text
    return ""


def item_turn_ids(item: dict[str, Any]) -> list[str]:
    refs: list[str] = []
    for field_name in GRAPH_TURN_ID_FIELDS:
        for turn_id in normalize_turn_ids(item.get(field_name)):
            if turn_id not in refs:
                refs.append(turn_id)
    return refs


def collect_inline_anchors_from_text(text: Any) -> list[str]:
    anchors: list[str] = []
    for match in ANCHOR_MARKER_RE.finditer(str(text or "")):
        anchor = match.group(1).strip()
        if anchor and anchor not in anchors:
            anchors.append(anchor)
    return anchors


def collect_legacy_anchor_strings(seed_row: dict[str, Any]) -> list[str]:
    anchors: list[str] = []
    for turn in dialogue_turns_from_row(seed_row):
        for anchor in collect_inline_anchors_from_text(turn.get("text")):
            if anchor not in anchors:
                anchors.append(anchor)
    for key in ("graph_dialogue_alignment", "current_alignment", "legacy_alignment"):
        value = seed_row.get(key)
        if isinstance(value, dict):
            for text in json.dumps(value, ensure_ascii=False).split('"'):
                if re.fullmatch(r"[A-Z0-9]{8,12}", text) and text not in anchors:
                    anchors.append(text)
    return anchors


def bootstrap_legacy_alignment(seed_row: dict[str, Any]) -> dict[str, Any]:
    """Recover best-effort provenance alignment from existing turn references.

    This is intentionally provenance-only. Its output is never used directly for
    final current-round QA/evidence unless the fact is re-realized and verified
    against the frozen current clean dialogue.
    """
    text_by_id = turn_text_by_id(seed_row)
    valid_turn_ids = set(text_by_id)
    legacy_alignment: dict[str, dict[str, Any]] = {}
    missing_total = 0

    def add_ref(key: str, raw_turn_ids: Any, source: str, expected_text: str = "") -> None:
        nonlocal missing_total
        refs = normalize_turn_ids(raw_turn_ids)
        if not refs:
            legacy_alignment.setdefault(
                key,
                {
                    "turn_ids": [],
                    "support_quotes": [],
                    "confidence": "low",
                    "source": "unknown",
                    "needs_reverbalization": True,
                },
            )
            return
        existing = [turn_id for turn_id in refs if turn_id in valid_turn_ids and text_by_id.get(turn_id)]
        missing = [turn_id for turn_id in refs if turn_id not in valid_turn_ids]
        missing_total += len(missing)
        confidence = "high" if existing and not missing and len(existing) == len(refs) else "low"
        support_quotes = [text_by_id[turn_id] for turn_id in existing[:5]]
        entry = legacy_alignment.setdefault(
            key,
            {
                "turn_ids": [],
                "support_quotes": [],
                "confidence": confidence,
                "source": source if confidence == "high" else "partial_refs",
                "needs_reverbalization": confidence != "high",
            },
        )
        for turn_id in existing:
            if turn_id not in entry["turn_ids"]:
                entry["turn_ids"].append(turn_id)
        for quote in support_quotes:
            if quote not in entry["support_quotes"]:
                entry["support_quotes"].append(quote)
        if expected_text:
            entry["expected_text"] = expected_text
        if confidence == "low":
            entry["confidence"] = "low"
            entry["source"] = "partial_refs"
            entry["needs_reverbalization"] = True

    qa = seed_row.get("qa") if isinstance(seed_row.get("qa"), dict) else {}
    add_ref("qa:evidence", qa.get("evidence_turn_ids"), "existing_valid_evidence_turn_ids", normalize_space(qa.get("question")))
    options = qa.get("options") if isinstance(qa.get("options"), list) else []
    for index, option in enumerate(options):
        if not isinstance(option, dict):
            continue
        label = normalize_space(option.get("id") or option.get("label") or LETTERS[index])
        add_ref(f"qa:option:{label}", option.get("turn_ids"), "existing_valid_evidence_turn_ids", normalize_space(option.get("text")))

    graph_update = seed_row.get("graph_update") if isinstance(seed_row.get("graph_update"), dict) else {}
    for index, event in enumerate(graph_update.get("events") or []):
        if isinstance(event, dict):
            event_ref = normalize_space(event.get("event_id") or event.get("node_id") or f"event_{index}")
            add_ref(f"graph_update.events[{index}]:{event_ref}", item_turn_ids(event), "existing_valid_evidence_turn_ids", item_text(event))
    for index, change in enumerate(graph_update.get("state_changes") or []):
        if isinstance(change, dict):
            change_ref = normalize_space(change.get("event_id") or change.get("node_id") or f"state_change_{index}")
            add_ref(
                f"graph_update.state_changes[{index}]:{change_ref}",
                change.get("evidence_turn_ids") or item_turn_ids(change),
                "existing_valid_evidence_turn_ids",
                normalize_space(change.get("to") or item_text(change)),
            )

    for key in ("graph_dialogue_alignment", "current_alignment", "legacy_alignment"):
        alignment = seed_row.get(key)
        if not isinstance(alignment, dict):
            continue
        for ref, payload in alignment.items():
            if isinstance(payload, dict):
                add_ref(f"{key}:{ref}", payload.get("turn_ids"), "existing_alignment_metadata")

    high = sum(1 for entry in legacy_alignment.values() if entry.get("confidence") == "high")
    low = sum(1 for entry in legacy_alignment.values() if entry.get("confidence") != "high")
    return {
        "legacy_alignment": legacy_alignment,
        "legacy_rows_with_missing_refs": 1 if missing_total else 0,
        "legacy_missing_ref_total": missing_total,
        "legacy_high_confidence_count": high,
        "legacy_low_confidence_count": low,
    }


def _weighted_choice(rng: random.Random, weights: dict[str, float], allowed: Iterable[str], defaults: dict[str, float]) -> str:
    items = []
    for key in allowed:
        try:
            weight = float(weights.get(key, defaults.get(key, 0.0)))
        except (TypeError, ValueError):
            weight = defaults.get(key, 0.0)
        items.append((key, max(0.0, weight)))
    total = sum(weight for _key, weight in items)
    if total <= 0:
        items = [(key, max(0.0, defaults.get(key, 1.0))) for key in allowed]
        total = sum(weight for _key, weight in items)
    threshold = rng.random() * total
    running = 0.0
    for key, weight in items:
        running += weight
        if running >= threshold:
            return key
    return items[-1][0]


def _curriculum_mode(policy: dict[str, Any] | None) -> str:
    if not isinstance(policy, dict):
        return "default"
    mode = normalize_space(policy.get("native_curriculum_mode"))
    if mode in ("r3_long_easy", EASY_V2_MODE):
        return mode
    return "default"


def _is_easy_curriculum(policy: dict[str, Any] | None) -> bool:
    # True for any easy variant (v1 or v2) so the shared easy knobs (length, event count,
    # natural phrasing, option cleanup) apply uniformly.
    return _curriculum_mode(policy) in ("r3_long_easy", EASY_V2_MODE)


def _is_easy_v2_curriculum(policy: dict[str, Any] | None) -> bool:
    return _curriculum_mode(policy) == EASY_V2_MODE


def _semantic_graph_v2_enabled(policy: dict[str, Any] | None) -> bool:
    if not isinstance(policy, dict):
        return False
    target = policy.get("stage64_target")
    return bool(
        policy.get("semantic_graph_v2")
        or policy.get("stage3_semantic_graph_v2")
        or (isinstance(target, dict) and normalize_space(target.get("qa_operation")))
    )


def _largest_remainder_quota(target_shares: dict[str, float], n: int) -> dict[str, int]:
    """Deterministic integer allocation summing exactly to n (largest-remainder)."""
    keys = list(target_shares.keys())
    total_share = sum(max(0.0, float(target_shares[k])) for k in keys) or 1.0
    raw = {k: max(0.0, float(target_shares[k])) / total_share * n for k in keys}
    floors = {k: int(raw[k]) for k in keys}
    remainder = n - sum(floors.values())
    # distribute the remaining units to the largest fractional parts, ties broken by key name
    order = sorted(keys, key=lambda k: (-(raw[k] - floors[k]), k))
    for i in range(remainder):
        floors[order[i % len(order)]] += 1
    return floors


class DeterministicQuotaScheduler:
    """Assigns an exact (question_type, attack_skill) plan per sample index for easy_v2.

    The plan is computed once from n_samples so the ACCEPTED distribution matches the
    target shares exactly (no weighted-sampling drift). Attack skills are round-robined
    within each question type's allowed easy set, so per-skill share is also bounded.

    The closed-loop difficulty controller may inject:
      - question_type_shares: override of the default EASY_V2 target shares (e.g. drop a
        mastered/bad cell's question type weight). Keys outside EASY_V2_SUPPORTED are ignored;
        a zero/empty share for a type removes it from the plan.
      - cell_weights: per (question_type, attack_skill) relative weight used to bias the
        within-type skill assignment toward band cells and away from too-hard/bad cells.
    """

    def __init__(
        self,
        n_samples: int,
        rng: random.Random,
        question_type_shares: dict[str, float] | None = None,
        cell_weights: dict[str, float] | None = None,
        cell_hardness_mix: dict[str, dict[str, float]] | None = None,
        single_choice_subtype_shares: dict[str, float] | None = None,
        single_choice_subtype_hardness_mix: dict[str, dict[str, float]] | None = None,
        hard_single_choice_template_shares: dict[str, float] | None = None,
    ) -> None:
        self.n_samples = int(n_samples)
        self.cell_hardness_mix = cell_hardness_mix or {}
        self.single_choice_subtype_hardness_mix = single_choice_subtype_hardness_mix or {}
        self.single_choice_subtype_shares = {
            str(key): max(0.0, float(value))
            for key, value in (single_choice_subtype_shares or {}).items()
            if max(0.0, float(value)) > 0
        }
        self.hard_single_choice_template_shares = {
            str(key): max(0.0, float(value))
            for key, value in (hard_single_choice_template_shares or {}).items()
            if str(key) in HARD_SINGLE_CHOICE_SUBTYPES and max(0.0, float(value)) > 0
        }
        shares = {q: float(EASY_V2_QUESTION_TYPE_TARGET_SHARES[q]) for q in EASY_V2_QUESTION_TYPE_TARGET_SHARES}
        if question_type_shares:
            override = {q: max(0.0, float(v)) for q, v in question_type_shares.items() if q in EASY_V2_SUPPORTED_QUESTION_TYPES}
            if override and sum(override.values()) > 0:
                shares = override
        # drop zero-share types entirely
        shares = {q: v for q, v in shares.items() if v > 0}
        if not shares:
            shares = {q: float(EASY_V2_QUESTION_TYPE_TARGET_SHARES[q]) for q in EASY_V2_QUESTION_TYPE_TARGET_SHARES}
        self.question_type_shares = shares
        self.cell_weights = {k: max(0.0, float(v)) for k, v in (cell_weights or {}).items()}
        qtype_quota = _largest_remainder_quota(shares, self.n_samples)
        # Build an interleaved queue of question types matching the exact quota, so any
        # prefix (e.g. a partial run) stays close to target shares.
        pools: list[tuple[str, int]] = sorted(qtype_quota.items(), key=lambda kv: (-kv[1], kv[0]))
        queue: list[str] = []
        counters = {q: 0 for q, _ in pools}
        remaining = dict(qtype_quota)
        while len(queue) < self.n_samples:
            # pick the qtype that is most "behind" its quota relative to its share
            best = None
            best_key = None
            for qtype, quota in pools:
                if remaining[qtype] <= 0:
                    continue
                progress = counters[qtype] / quota if quota else 1.0
                key = (progress, qtype)
                if best_key is None or key < best_key:
                    best_key = key
                    best = qtype
            if best is None:
                break
            queue.append(best)
            counters[best] += 1
            remaining[best] -= 1
        self.queue = queue
        self.qtype_quota = qtype_quota
        self._skill_rr: dict[str, int] = {q: 0 for q in EASY_V2_SUPPORTED_QUESTION_TYPES}
        self._hardness_rr: dict[str, int] = {}
        self._single_choice_subtype_rr = 0
        self._single_choice_subtype_queue: list[str] = []
        self._hard_single_choice_template_rr = 0
        self._hard_single_choice_template_queue: list[str] = []
        if self.single_choice_subtype_shares:
            target = int(qtype_quota.get("single_choice", 0))
            if target > 0:
                subtype_quota = _largest_remainder_quota(self.single_choice_subtype_shares, target)
                subtype_pool = sorted(subtype_quota.items(), key=lambda kv: (-kv[1], kv[0]))
                while len(self._single_choice_subtype_queue) < target:
                    best = None
                    best_key = None
                    for subtype, quota in subtype_pool:
                        if quota <= 0:
                            continue
                        used = self._single_choice_subtype_queue.count(subtype)
                        progress = used / quota if quota else 1.0
                        key = (progress, subtype)
                        if best_key is None or key < best_key:
                            best_key = key
                            best = subtype
                    if best is None:
                        break
                    self._single_choice_subtype_queue.append(best)
        hard_template_target = self._single_choice_subtype_queue.count("hard_single_choice")
        if self.hard_single_choice_template_shares and hard_template_target > 0:
            template_quota = _largest_remainder_quota(self.hard_single_choice_template_shares, hard_template_target)
            template_pool = sorted(template_quota.items(), key=lambda kv: (-kv[1], kv[0]))
            while len(self._hard_single_choice_template_queue) < hard_template_target:
                best = None
                best_key = None
                for template, quota in template_pool:
                    if quota <= 0:
                        continue
                    used = self._hard_single_choice_template_queue.count(template)
                    progress = used / quota if quota else 1.0
                    key = (progress, template)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = template
                if best is None:
                    break
                self._hard_single_choice_template_queue.append(best)
        self._rng = rng

    def _pick_single_choice_hardness(self, subtype: str, qtype: str, skill: str) -> str:
        if subtype in self.single_choice_subtype_hardness_mix:
            mix = self.single_choice_subtype_hardness_mix.get(subtype) or {}
            counts = _largest_remainder_quota({h: float(w) for h, w in mix.items() if float(w) > 0} or {"h0": 1.0}, 8)
            seq: list[str] = []
            for h in ("h0", "h1", "h2"):
                seq.extend([h] * counts.get(h, 0))
            if seq:
                rr = self._hardness_rr.get(f"single_choice|{subtype}", 0)
                self._hardness_rr[f"single_choice|{subtype}"] = rr + 1
                return seq[rr % len(seq)]
        return self._pick_hardness(qtype, skill)

    def _pick_hardness(self, qtype: str, skill: str) -> str:
        """Deterministic per-cell hardness from the controller's cell_hardness_mix (default h0)."""
        cell = f"{qtype}|{skill}"
        mix = self.cell_hardness_mix.get(cell)
        if not mix:
            return "h0"
        # expand the hardness mix into a small deterministic sequence, indexed by round-robin.
        counts = _largest_remainder_quota({h: float(w) for h, w in mix.items() if float(w) > 0} or {"h0": 1.0}, 8)
        seq: list[str] = []
        for h in ("h0", "h1", "h2"):
            seq.extend([h] * counts.get(h, 0))
        if not seq:
            return "h0"
        rr = self._hardness_rr.get(cell, 0)
        self._hardness_rr[cell] = rr + 1
        return seq[rr % len(seq)]

    def _pick_skill(self, qtype: str) -> str:
        skills = EASY_V2_ATTACK_SKILLS_BY_QUESTION_TYPE.get(qtype) or tuple(EASY_ATTACK_SKILLS)
        # If the controller supplied cell weights, bias skill choice toward higher-weight
        # cells deterministically (largest cumulative weight by round-robin position).
        if self.cell_weights:
            weighted = [(s, self.cell_weights.get(f"{qtype}|{s}", 1.0)) for s in skills]
            total = sum(w for _, w in weighted)
            if total > 0:
                # deterministic: expand into a quota-like sequence by weight, index by rr
                seq: list[str] = []
                counts = _largest_remainder_quota({s: w for s, w in weighted}, max(len(skills), 8))
                for s in skills:
                    seq.extend([s] * counts.get(s, 0))
                if seq:
                    rr = self._skill_rr.get(qtype, 0)
                    self._skill_rr[qtype] = rr + 1
                    return seq[rr % len(seq)]
        rr = self._skill_rr.get(qtype, 0)
        self._skill_rr[qtype] = rr + 1
        return skills[rr % len(skills)]

    def plan_for_index(self, index: int) -> dict[str, str]:
        if not self.queue:
            qtype = EASY_V2_SUPPORTED_QUESTION_TYPES[index % len(EASY_V2_SUPPORTED_QUESTION_TYPES)]
        else:
            qtype = self.queue[index % len(self.queue)]
        skill = self._pick_skill(qtype)
        hardness = self._pick_hardness(qtype, skill)
        if qtype == "single_choice":
            if self._single_choice_subtype_queue:
                difficulty_subtype = self._single_choice_subtype_queue[self._single_choice_subtype_rr % len(self._single_choice_subtype_queue)]
                self._single_choice_subtype_rr += 1
            else:
                difficulty_subtype = "ordinary_single_choice"
            hard_single_choice_template = "ordinary_single_choice"
            if difficulty_subtype == "hard_single_choice":
                if self._hard_single_choice_template_queue:
                    hard_single_choice_template = self._hard_single_choice_template_queue[
                        self._hard_single_choice_template_rr % len(self._hard_single_choice_template_queue)
                    ]
                else:
                    hard_single_choice_template = HARD_SINGLE_CHOICE_SUBTYPES[
                        self._hard_single_choice_template_rr % len(HARD_SINGLE_CHOICE_SUBTYPES)
                    ]
                self._hard_single_choice_template_rr += 1
            hardness = self._pick_single_choice_hardness(difficulty_subtype, qtype, skill)
        else:
            difficulty_subtype = "ordinary"
            hard_single_choice_template = "ordinary"
        return {
            "question_type": qtype,
            "attack_skill": skill,
            "distractor_hardness": hardness,
            "difficulty_subtype": difficulty_subtype,
            "hard_single_choice_template": hard_single_choice_template,
        }


def choose_question_type(policy: dict[str, Any] | None, rng: random.Random) -> str:
    policy = policy or {}
    # easy_v2 uses a deterministic per-sample plan injected via policy; honor it exactly.
    planned = normalize_space((policy.get("planned_cell") or {}).get("question_type")) if isinstance(policy.get("planned_cell"), dict) else ""
    if _is_easy_v2_curriculum(policy):
        if planned in EASY_V2_SUPPORTED_QUESTION_TYPES:
            return planned
        # No silent ordering fallback: fail loud rather than drift the distribution.
        raise NativeGraphDialogueReject(f"easy_v2 missing/invalid planned question_type: {planned!r}")
    easy = _is_easy_curriculum(policy)
    supported = EASY_SUPPORTED_QUESTION_TYPES if easy else SUPPORTED_QUESTION_TYPES
    default_weights = EASY_QUESTION_TYPE_WEIGHTS if easy else DEFAULT_QUESTION_TYPE_WEIGHTS
    weights = policy.get("question_type_weights") if isinstance(policy.get("question_type_weights"), dict) else {}
    requested = normalize_space(policy.get("question_type") or policy.get("requested_question_type"))
    if requested in supported:
        return requested
    return _weighted_choice(rng, weights, supported, default_weights)


def choose_attack_skill(question_type: str, policy: dict[str, Any] | None, rng: random.Random) -> str:
    policy = policy or {}
    if _is_easy_v2_curriculum(policy):
        planned = normalize_space((policy.get("planned_cell") or {}).get("attack_skill")) if isinstance(policy.get("planned_cell"), dict) else ""
        if planned:
            return planned
        raise NativeGraphDialogueReject(
            f"easy_v2 missing/invalid planned attack_skill {planned!r} for {question_type}"
        )
    easy = _is_easy_curriculum(policy)
    if easy:
        allowed = EASY_ATTACK_SKILLS_BY_QUESTION_TYPE.get(question_type, EASY_ATTACK_SKILLS)
        approved = EASY_ATTACK_SKILLS
    else:
        allowed = ATTACK_SKILLS_BY_QUESTION_TYPE.get(question_type, APPROVED_ATTACK_SKILLS)
        approved = APPROVED_ATTACK_SKILLS
    weights = policy.get("attack_skill_weights") if isinstance(policy.get("attack_skill_weights"), dict) else {}
    default = {skill: 1.0 for skill in allowed}
    chosen = _weighted_choice(rng, weights, allowed, default)
    return chosen if chosen in approved else allowed[0]


def choose_difficulty_subtype(question_type: str, policy: dict[str, Any] | None, rng: random.Random) -> str:
    policy = policy or {}
    planned = normalize_space((policy.get("planned_cell") or {}).get("difficulty_subtype")) if isinstance(policy.get("planned_cell"), dict) else ""
    if question_type == "single_choice":
        if planned == "hard_single_choice":
            return "hard_single_choice"
        return "ordinary_single_choice"
    return "ordinary"


